"""Original, source-linked action pairs for conditional work-queue exercises.

Each pair changes a legally material action/condition, not a person's name.
These are author-checked learning propositions, not an independent audit.
"""
GROUPS={}

def group(key, title, area, units, context, authority):
    GROUPS[key] = dict(key=key,title=title,area=area,units=units,context=context,authority=authority,atoms=[])

def add(key, good, bad, reason, *, units=None):
    g=GROUPS[key]; n=len(g['atoms'])+1
    g['atoms'].append(dict(id=f'{key}-{n:02}',good=good,bad=bad,reason_ko=reason,units=units or g['units'],authority=g['authority']))

# All circumstances not changed by an option remain as expressly stated in that option.
group('CE','Continuing-education record review',1,['w1-a-6','w1-a-7','w1-a-8'],
      'A Massachusetts pharmacist is reconciling continuing-education records before renewal. None of the pharmacists qualifies for military or hardship relief unless stated.',
      '247 CMR 4.03; Policy 2021-04, revised September 4, 2025')
add('CE','A pharmacist records 20 eligible contact hours in each calendar year of the renewal cycle.','A pharmacist records 40 eligible contact hours in the first year and none in the second year of the cycle.','연간 최소 20시간과 2년 합계 40시간을 모두 충족해야 한다. 합계만 맞춰 한 해의 부족을 상쇄할 수 없다.')
add('CE','A pharmacist applies an approved live law hour to both category requirements but counts one hour toward the annual total.','A pharmacist applies an approved live law hour to both categories and adds two hours to the annual total.','하나의 교육은 live와 law 요건에 동시에 해당할 수 있지만 실제 총 contact hours를 두 배로 계산하지 않는다.')
add('CE','A pharmacist claims eight eligible hours from a ten-hour CE conference held on a single calendar day.','A pharmacist claims all ten eligible hours from a CE conference held on a single calendar day.','Policy 2021-04는 하루 인정 상한을 8 contact hours로 정한다. 수강 시간과 인정 시간을 분리한다.')
add('CE','A pharmacist meets the law requirement with two approved home-study hours concerning another US jurisdiction.','A pharmacist replaces both required law hours with two hours of general clinical pharmacotherapy.','연간 law 2시간은 MA-specific 또는 live일 필요가 없지만 law로 인정되는 교육이어야 한다.')
add('CE','A pharmacist who directly supervises vaccination completes one ACPE-approved immunization hour for that calendar year.','A pharmacist who directly supervises vaccination omits immunization CE because another person gives every injection.','실제 투약자뿐 아니라 예방접종을 직접 감독하는 pharmacist도 해당 연도의 immunization CE 1시간이 필요하다.')
add('CE','A CDTM pharmacist completes 25 annual hours, including five additional hours related to the agreement.','A CDTM pharmacist completes 20 annual hours and treats five of those hours as the entire additional CDTM requirement.','CDTM는 일반 20시간에 관련 5시간을 추가하여 총 25시간이다. 일반 20시간 안에 모두 포함시키지 않는다.')
add('CE','A pharmacist temporarily verifying finished sterile preparations includes five eligible sterile-compounding CE hours.','A pharmacist temporarily verifying finished sterile preparations skips sterile CE because no ingredients were mixed personally.','직접 혼합하지 않아도 CSP의 최종검수·감독 업무는 해당 specialized CE trigger이다. 잠깐의 업무라고 자동 면제되지 않는다.')
add('CE','A pharmacist retains a qualifying non-ACPE certificate that does not appear in CPE Monitor.','A pharmacist discards a qualifying non-ACPE certificate because CPE Monitor is the only permitted record.','허용되는 non-ACPE credit의 별도 증빙을 보존한다. CPE Monitor에 없다는 이유로 증빙 의무가 사라지지 않는다.')
add('CE','A pharmacist licensed by transfer on October 5 uses the stated grace period to finish the prior year’s requirements by April 30.','A pharmacist licensed by transfer on October 5 treats the remainder of that calendar year as an automatic CE exemption.','10월 1일 이후 신규/transfer license는 다음 해 4월 30일까지의 grace period이며 졸업연도 면제와 다르다.')
add('CE','A pharmacist unable to complete the required hours emails the Board a detailed explanation rather than making a false attestation.','A pharmacist unable to complete the required hours attests compliance and plans to report the shortage at the next renewal.','현재 CE policy의 미충족 통지는 상세 사유를 Board에 email하는 방식이다. 통지가 면제 승인을 의미하지 않으며 허위 attestation은 해결책이 아니다.')

group('PERSON','Personnel assignment and professional judgment',1,['w1-b-1','w1-b-6','w1-b-7'],
      'At a Massachusetts community pharmacy, the pharmacist is on duty and available. Each proposed assignment below is evaluated with the employee’s current state license and certification.',
      'Policy 2020-15 §§I–III; 247 CMR 8.02–8.05; 247 CMR 9.04(1)')
add('PERSON','A fully licensed technician without national certification accepts an unchanged verbal refill authorization for lisinopril.','A pharmacy technician trainee accepts an unchanged verbal refill authorization for lisinopril.','변경 없는 III–VI refill authorization은 일반 licensed technician에게 가능하지만 PTT에게는 허용되지 않는다.')
add('PERSON','A licensed nationally certified technician accepts a new verbal prescription for gabapentin with pharmacist approval.','A licensed technician without national certification accepts a new verbal prescription for gabapentin with pharmacist approval.','새 III–VI verbal prescription은 certified technician의 추가 권한이다. pharmacist의 단순 승인으로 ordinary technician의 범위를 확대하지 않는다.')
add('PERSON','A licensed pharmacist receives an emergency oral oxycodone authorization directly from the prescribing practitioner.','A nationally certified technician receives an emergency oral oxycodone authorization directly from the prescribing practitioner.','Emergency oral CII는 practitioner→pharmacist 경로이다. Certified technician의 새 III–VI 전화처방 권한을 CII에 적용하지 않는다.')
add('PERSON','A supervised Massachusetts intern counsels a patient about a newly prescribed inhaler.','A supervised nationally certified technician counsels a patient about a newly prescribed inhaler.','실제 counseling은 pharmacist 또는 적절한 감독을 받는 intern의 업무이다. Technician는 offer를 전달할 수 있지만 임상 상담을 대신하지 않는다.')
add('PERSON','A pharmacist performs final patient-specific prescription verification after an intern prepares the medication.','An intern performs final patient-specific prescription verification because the supervising pharmacist is nearby.','Intern의 넓은 보조 scope에도 final prescription verification 예외가 남는다.')
add('PERSON','A certified technician makes a permitted Schedule II perpetual-inventory entry subject to the pharmacy’s controls.','A certified technician adjusts an unexplained Schedule II shortage out of the perpetual inventory without pharmacist review.','허용된 entry와 discrepancy adjustment는 다르다. MOR 또는 해당 pharmacist의 조정·조사 권한을 certified technician에게 자동 부여하지 않는다.')
add('PERSON','A trained cashier hands over a filled, verified, bagged prescription and offers pharmacist counseling.','A trained cashier selects an unfilled prescription stock bottle and counts tablets before ringing up the sale.','Unlicensed cashier의 완성된 봉투 전달/offer는 unfinished prescription drug handling 권한이 아니다.')
add('PERSON','An external maintenance worker enters the prescription area while accompanied and monitored by a pharmacist.','An external maintenance worker enters the prescription area alone because the pharmacy has issued a visitor badge.','외부 vendor의 출입은 pharmacist 동행·감시 조건이 필요하다. 방문증만으로 대체되지 않는다.')
add('PERSON','A certified technician transfers an otherwise eligible Schedule VI prescription with pharmacist approval.','A certified technician transfers an otherwise eligible Schedule IV prescription with pharmacist approval.','Certified technician의 MA transfer 범위는 VI이다. Federal III–V pharmacist-to-pharmacist requirement를 pharmacist 승인만으로 없애지 않는다.')
add('PERSON','A technician gathers a medication history and refers a newly identified interaction to the pharmacist.','A technician gathers a medication history and independently resolves the interaction by changing the dose.','정보 수집과 임상 판단·치료 변경은 별개이다. Technician가 DUR와 clinical issue resolution을 맡을 수 없다.')

group('STAFF','Supervision and training assignments',1,['w1-b-8','w1-b-9','w1-b-10','w1-b-11'],
      'The manager is reviewing staffing assignments under Massachusetts Policy 2026-02. The stated support personnel are actively assisting prescription preparation unless the option specifies another role.',
      'Policy 2026-02 §§I–III, adopted September 3, 2026')
add('STAFF','One pharmacist supervises four support staff consisting of two certified technicians and two ordinary technicians.','One pharmacist supervises four support staff consisting of one certified technician and three ordinary technicians.','일반 1:4에는 certified 2명, intern 2명 또는 각각 1명 조합이 필요하다. Certified 1명만 있으면 이 4명 조합을 충족하지 않는다.')
add('STAFF','One pharmacist supervises three support staff including one licensed intern and two ordinary technicians.','One pharmacist supervises three support staff who are all ordinary technicians.','일반 1:3에는 licensed intern 또는 certified technician이 적어도 1명 필요하다.')
add('STAFF','A pharmacy providing vaccination services uses six support staff, including three certified technicians.','A pharmacy not providing vaccination services uses the special six-support-staff ratio based only on having three certified technicians.','특례 1:6의 전제에는 vaccination services가 포함된다. 직원 자격만으로 일반 조제 환경에 이 비율을 자동 적용하지 않는다.')
add('STAFF','A licensed employee assigned only to non-filling inventory duties is excluded from the ratio, with that role posted.','A licensed employee filling prescriptions is excluded from the ratio because the posted title is inventory specialist.','실제 업무가 professional prescription preparation/filling을 지원하는지 확인한다. 직함만 바꾸어 ratio에서 제외할 수 없다.')
add('STAFF','A dedicated trainer is excluded while directly overseeing the trainee and doing no independent professional support work.','A dedicated trainer is excluded while independently filling prescriptions between trainee demonstrations.','Trainer 제외는 독립적인 pharmacist-support 업무를 하지 않는 조건이다. 그 경계를 넘으면 ratio 포함 여부를 다시 판단한다.')
add('STAFF','A nationally certified employee receiving dedicated training is counted as an ordinary technician for that training assignment.','A nationally certified employee receiving dedicated training supplies the qualifying certified slot for that training assignment.','Dedicated trainee는 실제 자격이 certified/intern이어도 해당 assignment에서는 ordinary pharmacy technician으로 계산한다.')
add('STAFF','An employee scheduled exclusively for computer training is excluded while doing no professional support work.','An employee scheduled for computer training is excluded while also interrupting modules to fill waiting prescriptions.','Computer-only exclusion에는 지정 일정과 오직 computer training, professional support 업무 없음이라는 조건이 필요하다.')
add('STAFF','A pharmacist preceptor directly supervises four interns during an exclusively immunization clinic.','A pharmacist preceptor directly supervises four interns who also fill prescriptions throughout the clinic.','최대 4 intern의 예방접종 예외는 exclusively immunization clinic이다. 일반 filling을 섞으면 통상의 intern 감독 경계를 유지한다.')
add('STAFF','A domestic pharmacy student receives a Massachusetts intern license before beginning a hospital internship.','A domestic pharmacy student begins a hospital internship using student identification while the intern license is pending.','정책은 domestic/foreign 모두 어떤 setting의 internship 시작 전에도 MA intern license를 확인하도록 한다.')
add('STAFF','A trainer and trainee are designated on the posted schedule before the training day, with written procedures in place.','A manager retrospectively labels ordinary shifts as dedicated training after discovering an excessive staffing ratio.','Dedicated training은 사전 일정·명찰·감독·P&P 조건을 갖춘 실제 업무형태이다. 사후 명칭 변경으로 초과 staffing을 치유하지 않는다.')

group('LICENSE','Individual and facility licensure',1,['w1-a-2','w1-a-3','w1-a-4','w1-a-5','w1-c-1','w1-c-2'],
      'A Massachusetts employer is evaluating licensing records before authorizing work or opening a location. No special Board waiver or military exception has been granted.',
      '247 CMR 3.01–3.04, 4.02, 6.02–6.09')
add('LICENSE','A pharmacist waits for Massachusetts license issuance before beginning independent pharmacist duties.','A pharmacist begins independent Massachusetts duties after passing MPJE while license issuance remains pending.','시험 합격과 면허 발급은 다른 단계이다. 유효한 MA 면허 없이 독립 pharmacist 업무를 시작하지 않는다.')
add('LICENSE','An Idaho-licensed pharmacist uses the Massachusetts reciprocity process and completes the remaining MA requirements.','An Idaho-licensed pharmacist treats the Idaho license as authorization to practice independently in Massachusetts.','Reciprocity는 자동 면허 대체가 아니다. NABP/Board 심사와 해당 MA 요건이 남는다.')
add('LICENSE','A reciprocity applicant tracks the application’s one-year validity from NABP approval.','A reciprocity applicant restarts the one-year validity each time a document is uploaded to the Board.','Reciprocity application의 규정상 1년 시작점은 NABP approval이다. 임의의 업로드 날짜가 새 시계를 만들지 않는다.')
add('LICENSE','A retired-status pharmacist refrains from active practice unless a lawful return to practice is approved.','A retired-status pharmacist covers a retail shift because retired status is nondisciplinary.','Nondisciplinary retirement와 active practice authorization은 다르다. Retired status 자체로 업무가 허용되지 않는다.')
add('LICENSE','A pharmacist retrieves an old certificate after obtaining a duplicate and returns the duplicate to the Board.','A pharmacist retrieves an old certificate after obtaining a duplicate and keeps both as independently usable registrations.','원본을 찾은 뒤 반환해야 하는 것은 duplicate certificate이다. 두 문서가 별개의 면허를 만드는 것은 아니다.')
add('LICENSE','A pharmacist whose ordinary renewal has lapsed stops practice until the registration is restored.','A pharmacist whose ordinary renewal has lapsed continues practice during the first 60 days of nonrenewal.','60일은 추가 복구조건 관련 기준이지 일반 업무 유예기간이 아니다. 만료 후 practice는 unlicensed practice이다.')
add('LICENSE','A retail pharmacy maintains its Drug Store license and obtains the additional license required for sterile compounding.','A retail pharmacy begins sterile compounding using only its ordinary Drug Store license.','일반 Drug Store와 sterile-compounding authorization은 별개이다. Institutional 경로의 예외를 일반 retail에 자동 적용하지 않는다.')
add('LICENSE','An out-of-state pharmacy obtains the applicable MA nonresident license before shipping prescription medications into Massachusetts.','An out-of-state pharmacy ships prescription medications into Massachusetts relying only on its home-state license.','MA로 처방약을 dispense/ship하는 nonresident pharmacy에는 적용되는 MA license가 필요하다.')
add('LICENSE','A pharmacy tracks its annual compounding-license renewal separately from its Drug Store license renewal.','A pharmacy treats a current Drug Store license as automatically renewing its expired compounding license.','한 약국이 여러 license를 보유하면 각 유형의 갱신 주기와 조건을 별도로 충족한다.')
add('LICENSE','A pharmacy obtaining Board application approval plans to open within one calendar year or obtains written permission for a later opening.','A pharmacy obtaining Board application approval assumes it can first open several years later without further written permission.','Board approval 후 1 calendar year 내 개업 또는 그 이후 개업에 대한 written permission 요건을 지킨다. License 갱신주기와 다른 규칙이다.')

group('MOR','Manager responsibilities and business changes',1,['w1-c-3','w1-c-4','w1-c-5','w1-c-7'],
      'A resident Massachusetts Drug Store pharmacy is planning operational changes. Any reporting deadlines expressly left unresolved in the notes are outside this question.',
      '247 CMR 6.10–6.16; 247 CMR 9.23')
add('MOR','A retail MOR works an average of at least 30 hours weekly at the managed pharmacy.','A retail MOR works an average of 20 hours weekly at the managed pharmacy and relies on full-time employment elsewhere.','Resident retail MOR의 평균 주 30시간은 관리하는 pharmacy에서 충족한다.')
add('MOR','A pharmacist serves as MOR for one retail Drug Store pharmacy.','A pharmacist serves concurrently as MOR for two retail Drug Store pharmacies with nonoverlapping opening hours.','일반 retail MOR는 동시에 둘 이상의 pharmacy의 MOR가 될 수 없다. 운영시간이 다르다는 이유로 자동 예외가 생기지 않는다.')
add('MOR','Outgoing and incoming MORs attest to an inventory including II–V and PMP-reportable VI drugs.','Outgoing and incoming MORs restrict the change inventory to Schedule II and omit all other controlled inventory.','MOR change inventory에는 II–V와 PMP-reportable VI가 포함된다. Routine CII reconciliation과 같은 범위로 축소하지 않는다.')
add('MOR','An incoming owner submits the required new pharmacy-license application rather than buying the prior license.','An incoming owner treats the signed bill of sale as transferring the old pharmacy license into the new owner’s name.','Pharmacy license는 non-transferable이다. 사업체 매매와 새 허가 신청은 별개이다.')
add('MOR','A pharmacy obtains required Board approval before remodeling its licensed prescription area.','A pharmacy completes a prescription-area expansion and asks for approval during the next renewal.','적용되는 configuration/square-footage/remodeling 변경은 시작 전 Board approval 경로를 따른다.')
add('MOR','A pharmacy files a relocation application at least 90 days in advance and waits for approval, absent a Board-approved exception.','A pharmacy files a relocation application 90 days in advance and moves without awaiting Board approval.','신청 기한과 사전 승인 요건을 각각 충족한다. 접수 자체가 relocation approval이 아니다.')
add('MOR','A pharmacy closing on a planned date identifies recently served patients and attempts the required advance notification.','A pharmacy closing on a planned date uses an announcement to staff as its only patient notification.','계획된 폐업에는 Board 통지와 환자별 통지·records transfer/continuity 절차가 별도로 필요하다.')
add('MOR','A departing MOR preserves the handover inventory in the required records while completing the proper change filings.','A departing MOR destroys the handover inventory after submitting the change application.','Inventory 보존과 Board change filing은 대체 관계가 아니다. 해당 보존기간·서명·attestation을 유지한다.')
add('MOR','An on-duty pharmacist maintains drug security despite having a different pharmacist designated as MOR.','An on-duty pharmacist delegates all drug-security responsibility to the absent MOR.','MOR의 관리책임과 on-duty pharmacist의 근무 중 보안·보관 책임은 함께 존재한다.')
add('MOR','A pharmacy requesting a waiver continues to follow the existing requirement until applicable relief is granted.','A pharmacy treats its pending waiver request as permission to stop following the requirement.','Waiver 신청과 승인된 면제는 다르다. Board가 면제할 수 없는 상위 법까지 임의로 배제할 수 없다.',units=['w4-d-17'])

group('COUNSEL','Counseling and patient understanding',2,['w3-b-1','w3-b-2','w3-b-3','w3-b-6','w3-b-7'],
      'A Massachusetts pharmacist is reviewing patient-facing procedures for outpatient prescriptions. Each patient is receiving medication rather than an inpatient medication order.',
      '247 CMR 9.18; 21 CFR 208.24, 310.501, 310.515')
add('COUNSEL','A trained designee offers counseling and directs clinical questions to the pharmacist.','A trained designee completes the clinical counseling because the pharmacist approved the printed handout.','Offer를 전달하는 일과 actual counseling은 다르다. Designee 교육이나 handout 승인만으로 임상 상담권한이 생기지 않는다.')
add('COUNSEL','An intern under appropriate pharmacist supervision explains a new medicine’s directions and important precautions.','A nationally certified technician explains a new medicine’s directions and important precautions as the clinical counselor.','환자 counseling은 pharmacist/intern의 역할이며 certified technician에게 일반적으로 위임할 수 없다.')
add('COUNSEL','A pharmacist records a patient’s actual refusal after offering available counseling.','A pharmacist records refusal because the patient is walking quickly toward the exit, without making an offer.','Refusal은 실제 제안과 환자의 선택에 근거해야 한다. 바쁜 모습만으로 거절을 추정하지 않는다.')
add('COUNSEL','A pharmacy provides a consultation area where the discussion can be visually and audibly confidential.','A pharmacy treats a marked spot in the public checkout queue as sufficient despite conversations being clearly overheard.','Consultation area는 visual·auditory confidentiality를 제공해야 한다. 표지만으로 공간의 보호요건을 대신하지 않는다.')
add('COUNSEL','A pharmacist supplies or recommends a suitable measuring device with an oral liquid.','A pharmacist substitutes an unmarked household spoon for any consideration of a suitable measuring device.','Liquid medication의 적절한 measuring device 제공/권고를 확인한다. 불명확한 가정용 숟가락은 적합성 확인의 대체가 아니다.')
add('COUNSEL','A pharmacist gives an applicable FDA Medication Guide with a refill requiring the Guide.','A pharmacist omits the required Medication Guide on refills because it was given with the original fill.','Medication Guide 제공은 해당 제품의 refill에도 적용될 수 있다. 최초 제공으로 이후 의무가 모두 없어지지 않는다.')
add('COUNSEL','A pharmacy gives the required Medication Guide in addition to its ordinary computer-generated information leaflet.','A pharmacy replaces the required Medication Guide with its ordinary computer-generated information leaflet.','일반 CMI와 FDA-approved Medication Guide는 같은 문서가 아니다.')
add('COUNSEL','A pharmacist provides the required patient package insert with each dispensed package of an oral contraceptive.','A pharmacist provides an oral-contraceptive patient package insert only when the patient requests one.','Oral contraceptive PPI는 해당 package마다 동봉/제공하는 의무가 있으며 요청이 전제는 아니다.')
add('COUNSEL','An acute-care hospital gives the oral-contraceptive PPI before first administration and every 30 days during continued therapy.','An acute-care hospital delays the first oral-contraceptive PPI until the first 30 days of therapy are complete.','기관의 PPI 경로는 최초 투약 전 제공과 이후 30일 주기를 구분한다.')
add('COUNSEL','A pharmacist assesses whether a clinically significant change warrants renewed counseling even though the patient has used the drug before.','A pharmacist excludes every previously used drug from counseling even when the directions have materially changed.','New therapy뿐 아니라 pharmacist judgment상 건강·안전에 중요한 therapy에도 상담을 수행한다. 과거 복용 경험만으로 변경사항을 제외하지 않는다.')

group('PRIVACY','Privacy and permitted disclosures',2,['w3-b-12','w3-b-13','w3-b-14','w3-b-15','w3-b-16','w6-a-11'],
      'A HIPAA-covered Massachusetts pharmacy receives requests involving identifiable patient information. No emergency disclosure exception or special judicial order applies unless stated.',
      '45 CFR 164.502, 164.506, 164.510, 164.524, 164.530; HIPAA Security Rule')
add('PRIVACY','A pharmacist contacts the actual treating prescriber about a clinically relevant prescription problem without demanding a separate patient authorization.','A pharmacist refuses necessary treatment communication with the actual prescriber solely because no separate patient authorization is on file.','허용된 treatment communication과 marketing authorization은 다른 경로다. 적절한 치료 목적 공개에 불필요한 별도 허가를 일반 요건으로 만들지 않는다.')
add('PRIVACY','A pharmacy limits billing staff access to information needed for their assigned payment work.','A pharmacy gives billing staff unrestricted access to every patient record for personal curiosity.','TPO 허용은 workforce의 호기심 열람을 허용하는 것이 아니다. 업무별 access control·minimum necessary를 적용한다.')
add('PRIVACY','A pharmacy verifies a patient’s identity before providing the patient access to the designated record set.','A pharmacy sends the full record to an unidentified caller solely because the caller knows the patient’s medication name.','환자 접근권을 존중하면서 identity와 수신권한을 확인해야 한다. 약 이름 지식만으로 본인임을 확정하지 않는다.')
add('PRIVACY','A pharmacy provides a family member involved in pickup only information relevant to that involvement, using the applicable permission or professional-judgment basis.','A pharmacy gives a family member the entire prescription history solely because that person is collecting one prescription.','Family/pickup의 제한된 관여는 전체 기록의 무제한 접근권과 다르다.')
add('PRIVACY','A pharmacy acts on a patient access request within 30 calendar days unless a compliant extension is used.','A pharmacy restarts the patient-access response clock when its record-storage vendor forwards the request internally.','환자 접근의 30 calendar days는 요청 수령 기준이다. Vendor/internal 전달로 새 시계가 생기지 않는다.')
add('PRIVACY','A pharmacy needing the one permitted access extension explains the reason and completion date in writing during the initial 30-day period.','A pharmacy silently takes repeated 30-day extensions because its records are stored offsite.','한 번의 최대 30일 연장에는 최초 기간 안의 서면 사유·예정일 통지가 필요하다.')
add('PRIVACY','A pharmacy preserves required HIPAA documentation for the applicable six-year period while applying separate prescription-record laws.','A pharmacy uses the ordinary two-year prescription retention minimum to discard all HIPAA-required documentation at two years.','HIPAA documentation의 6년과 일반 처방기록 보존은 다른 자료별 요건이다.')
add('PRIVACY','A pharmacy enters an appropriate business-associate arrangement with a billing service handling PHI on its behalf.','A pharmacy assumes the billing vendor’s general confidentiality promise removes the need to evaluate business-associate requirements.','Pharmacy를 대신하여 PHI를 처리하는 관계는 applicable business-associate requirements를 확인한다. 일반 비밀유지 약속만으로 판단을 생략하지 않는다.')
add('PRIVACY','A pharmacy distinguishes the privacy of paper records from safeguards specifically required for electronic PHI.','A pharmacy treats the Security Rule as its only obligation and leaves printed patient records publicly exposed.','Privacy는 paper/oral/electronic PHI를 포함할 수 있고 Security는 ePHI 보호의 별도 층이다.')
add('PRIVACY','A pharmacy obtains the applicable authorization before using patient lists for an unrelated outside company’s marketing.','A pharmacy treats selling identifiable patient lists for an outside advertisement as routine treatment communication.','외부 홍보·PHI 판매를 일반 treatment communication으로 이름만 바꾸어 처리하지 않는다. 적용 authorization 요건을 확인한다.')

group('DUR','Patient profiles and professional review',2,['w3-b-4','w3-b-5','w2-a-5','w4-a-7'],
      'During outpatient prescription processing, the pharmacist is deciding whether the proposed review and documentation steps are sufficient.',
      '247 CMR 9.15–9.19; 21 CFR 1306.04')
add('DUR','A pharmacist reviews relevant allergies before delivering a new prescription to the patient’s agent.','A pharmacist postpones the new-prescription allergy review until after the patient’s agent has left with the drug.','Prospective DUR는 new prescription/order의 교부 또는 delivery 전에 수행한다.')
add('DUR','A pharmacist investigates a clinically important interaction alert and documents the measure taken.','A pharmacist clears a clinically important interaction alert without assessment because the computer allows an override.','Software override 가능성과 적절한 clinical review는 다르다. 문제를 평가하고 대응 내용을 기록한다.')
add('DUR','A pharmacist makes a reasonable effort to clarify an unknown allergy history rather than recording it as confirmed absent.','A pharmacist records no known allergies solely because the allergy field is blank.','정보 없음과 알레르기 없음 확인은 다르다. Profile에는 합리적인 정보수집 노력을 반영한다.')
add('DUR','A pharmacist assesses a legitimate-purpose concern even though the submitted DEA number has a valid check digit.','A pharmacist closes a legitimate-purpose concern solely because the submitted DEA number has a valid check digit.','DEA 형식/check digit는 진정성·현재 등록·scope·legitimate medical purpose를 모두 입증하지 않는다.')
add('DUR','A pharmacist documents relevant action after discussing a dose discrepancy with the prescriber.','A pharmacist leaves no record of the action because the prescriber discussion occurred by telephone.','DUR에 대응하여 취한 조치는 문서화한다. 통화라는 방식이 기록 의무를 없애지 않는다.')
add('DUR','A pharmacist considers patient-specific significance when deciding how to resolve a computerized alert.','A pharmacist treats every alert as an automatic statutory prohibition regardless of its patient-specific relevance.','Alert는 professional judgment의 자료이다. 모든 alert를 자동 금지로 취급하거나 모두 무시하는 두 극단을 피한다.')
add('DUR','A pharmacy obtains patient or agent consent before enrolling the patient in automatic refills.','A pharmacy uses a successful insurance refill claim as the patient’s automatic-refill enrollment consent.','보험 청구 가능성과 automatic-refill program 동의는 다르다.')
add('DUR','A pharmacy’s downtime procedure includes later reconciliation of manually documented dispensing into the patient profile.','A pharmacy discards downtime records once the computer restarts without incorporating the missing dispensing history.','시스템 복구 후 누락 없는 기록 복원이 필요하다. Downtime은 이후 profile 의무의 면제가 아니다.')
add('DUR','A pharmacist separately verifies product accuracy and the prescription’s legal legitimacy.','A pharmacist treats a successful barcode match as completing the legal-purpose and prescriber-authority assessment.','정확한 product와 적법한 prescription은 서로 다른 검수 축이다.')
add('DUR','A pharmacist maintains the actual product and relevant comments so prior therapy can be retrieved at the next dispensing.','A pharmacy relies on the patient remembering all prior therapy instead of maintaining the required confidential profile.','약국은 필요한 정보를 즉시 검색 가능한 confidential patient profile로 유지한다.')

group('VACC','Vaccination qualifications and workflow',2,['w3-c-1','w3-c-2','w3-c-3','w3-c-4','w3-c-5','w3-c-6','w3-c-8'],
      'A Massachusetts pharmacy is using the state vaccine-administration pathway, not an independent federal PREP Act exception. All products are appropriate for the stated patient unless an option says otherwise.',
      'Policy 2023-02 (revised September 4, 2025); 105 CMR 222.100–222.105')
add('VACC','A fully licensed technician with current national certification completes required vaccine training, CPR, and supervised administration conditions before vaccinating.','A fully licensed technician uses national certification alone as a substitute for vaccine training, CPR, and supervision.','National certification은 technician 적격성 경로의 일부이다. 백신 교육·CPR·감독 조건을 대체하지 않는다.')
add('VACC','A noncertified fully licensed technician counts at least 500 hours worked after full technician licensure toward the experience pathway.','A noncertified fully licensed technician uses only hours worked as a trainee to satisfy the post-licensure 500-hour pathway.','경험 경로는 full PT licensure 이후 시간이다. PTT 시간과 구별한다.')
add('VACC','A technician trainee assists with permitted non-injection tasks but does not give vaccinations under the state policy.','A technician trainee gives a vaccination after completing the technician vaccine course while still holding only trainee status.','주 정책은 full Pharmacy Technician license를 전제로 하고 PTT를 포함하지 않는다.')
add('VACC','A pharmacist selects the vaccine and counsels before a properly qualified technician prepares and administers it.','A qualified technician independently selects a vaccine and performs the clinical counseling before administering it.','기술적 preparation/administration 허용과 vaccine selection/clinical counseling 권한은 다르다.')
add('VACC','A vaccinator keeps current CPR certification while performing injections.','A vaccinator relies on expired CPR certification because the initial vaccine course was previously passed.','실제 투약 인력은 current CPR를 유지한다. 초기 교육 완료와 현재 CPR 유효성은 별개이다.')
add('VACC','A pharmacy maintains valid vaccine orders and separate applicable orders for emergency reaction medications.','A pharmacy assumes any vaccine prescription automatically authorizes every emergency medication in its reaction kit.','백신 order와 adverse-event emergency medication order를 구별한다.')
add('VACC','A pharmacy gives the applicable VIS to the patient or representative before vaccination.','A pharmacy gives the applicable VIS only with the receipt after vaccination is finished.','VIS는 사전 정보 제공이다. 사후 영수증에 넣는 것으로 대체되지 않는다.')
add('VACC','A pharmacist checks MIIS before a routine shingles vaccination under the state policy.','A pharmacist skips the required pre-administration MIIS check for shingles because influenza has an exception.','Influenza/COVID의 특정 조회 예외를 다른 routine vaccines에 확대하지 않는다.')
add('VACC','A pharmacy reports a routine vaccine administration to MIIS within the applicable 72-hour period.','A pharmacy delays routine MIIS reporting until its monthly billing reconciliation.','일반 immunization reporting은 투약 후 72시간이다. 월별 청구 일정과 별개이다.')
add('VACC','A provider honors a patient’s MIIS data-sharing objection while continuing required reporting to the Department.','A provider deletes the reporting obligation after the patient objects to sharing with other MIIS sites.','Sharing objection은 Department reporting 자체의 거부권이 아니다.')

group('ADMIN','Medication administration under the 2026 circular',2,['w3-c-12','w3-c-13','w3-c-14','w3-c-15','w3-c-16','w3-c-17'],
      'A Massachusetts retail pharmacy offers medication administration under DCP 26-03-124. The cases do not involve a hospital privilege or a separately authorized opioid treatment program.',
      'DCP 26-03-124, March 11, 2026')
add('ADMIN','A trained pharmacist with current CPR administers an eligible single-dose LAI to an adult under a valid prescription and product requirements.','A trained pharmacist uses the circular to administer the same LAI to a 16-year-old without another lawful authority.','본 circular의 일반 대상은 18세 이상이다. 다른 예방접종 또는 prescribing 경로의 연령을 옮겨 쓰지 않는다.')
add('ADMIN','A qualified intern administers an eligible adult patient’s IM medication under appropriate pharmacist supervision.','A certified technician administers an adult patient’s non-vaccine LAI solely under this circular.','DCP 26-03-124의 대상 인력은 pharmacist와 pharmacy intern이다. Technician vaccine scope와 구별한다.')
add('ADMIN','A pharmacy administers eligible ceftriaxone by the labeled IM route within the circular’s conditions.','A pharmacy administers ceftriaxone intravenously using the circular’s IM authorization.','해당 경로는 IV가 아니며 eligible medication의 SC/IM 제조사 지시를 따른다.')
add('ADMIN','A pharmacist uses an eligible product in single-dose packaging prescribed in single doses, with authorized refills as applicable.','A pharmacist uses a multidose supply as the basis for bypassing the circular’s single-dose packaging requirement.','Single-dose packaging와 prescribed single doses는 별도 조건이다. Refill이 있다는 사실과 multidose packaging은 같지 않다.')
add('ADMIN','A pharmacist checks medication-specific training and current competency before adding a newly eligible administration service.','A pharmacist assumes an old vaccine certificate establishes competency for every newly eligible non-vaccine medication.','해당 약물·환자군과 injection technique에 맞는 교육·continued competency를 확인한다.')
add('ADMIN','A pharmacy documents patient consent, screening, lot, expiry, administration route/site, and administering professional.','A pharmacy keeps only the insurance claim and omits the administration-specific patient and product records.','약물 교부 청구기록이 administration의 consent·screening·제품·행위 기록을 모두 대체하지 않는다.')
add('ADMIN','A pharmacist immediately informs the prescriber after an administration reaction requiring emergency-department monitoring.','A pharmacist waits for the next routine progress report after an administration reaction requiring emergency-department monitoring.','Hospital/ED 추가 treatment/testing/monitoring 등 지정 serious outcome이면 즉시 prescriber 통지 경로이다.')
add('ADMIN','A pharmacist distinguishes administering a prescribed HIV-prevention medication from independently prescribing every prevention regimen.','A pharmacist treats permission to administer an HIV-prevention medication as authority to independently prescribe all prevention regimens.','Administer와 prescribe는 별도의 법적 권한이며 상세 prescribing protocol를 대체하지 않는다.')
add('ADMIN','A pharmacist follows labeling and applicable REMS for an eligible long-acting buprenorphine injection.','A pharmacist ignores applicable REMS because the state circular lists the active ingredient as eligible.','주 administration eligibility는 제품별 labeling·REMS를 없애지 않는다.')
add('ADMIN','A retail pharmacist recognizes that the circular does not create ordinary retail methadone administration for OUD outside an OTP.','A retail pharmacist starts ordinary OUD methadone administration outside an OTP because the circular discusses addiction medications.','Circular는 addiction methadone administration을 registered OTP의 order 경로로 제한하는 문구를 갖는다. 일반 retail로 확대하지 않는다.')

group('CDTM','Collaborative therapy management',2,['w3-d-2','w3-d-3','w3-d-4','w3-d-6','w3-d-7','w3-d-8','w3-d-9','w3-d-10'],
      'A Massachusetts community pharmacy is evaluating a CDTM arrangement. The question concerns the retail CDTM pathway, not a separate statewide prescribing statute.',
      '247 CMR 16.02–16.04; Board CDTM educational-equivalency advisory')
add('CDTM','A qualified pharmacist maintains insurance specifically covering drug-therapy management at at least $1 million per occurrence.','A qualified pharmacist treats any employer general-liability policy as sufficient without checking drug-therapy-management coverage.','CPA 기간 중 해당 drug-therapy-management를 보장하는 professional liability coverage를 확인한다.')
add('CDTM','A new PharmD graduate seeks an applicable experience or Board-equivalency pathway before assuming CDTM eligibility.','A new PharmD graduate uses the pre-June-2017 grandfather provision as automatic qualification for a newly created agreement.','과거 날짜가 붙은 PharmD grandfather 경로를 새 졸업자에게 무조건 적용하지 않는다. 현재 경험·equivalency 요건이 남는다.')
add('CDTM','A retail CDTM pharmacist receives the supervising physician’s patient-specific written referral and diagnosis information.','A retail CDTM pharmacist substitutes a general store sign-up form for the physician’s patient-specific written referral.','Retail CDTM는 written physician referral와 지정 diagnosis를 필요로 한다. 일반 서비스 신청으로 대체하지 않는다.')
add('CDTM','A retail CDTM pharmacist manages an adult patient within the physician referral, signed agreement, and authorized Schedule VI scope.','A retail CDTM pharmacist prescribes alprazolam because the physician added it to the retail agreement.','Retail/community CPA라도 Schedule II–V prescribing 제한을 계약으로 없앨 수 없다.')
add('CDTM','A retail program confirms the patient is at least 18 before using this CDTM pathway.','A retail program applies the separate minor-contraception consent rule to remove CDTM’s adult-patient requirement.','환자 연령은 실제 사용하는 법적 경로에 따라 판단한다. 별도 contraception authority를 CDTM에 복사하지 않는다.')
add('CDTM','A pharmacist communicates an initial prescription or therapy change to the supervising physician within 24 hours, sooner if urgent.','A pharmacist waits until the CPA’s next biennial review to communicate an initial prescription or therapy change.','Patient action별 24시간 communication과 CPA의 2년 review/renewal는 별개이다.')
add('CDTM','The pharmacist and supervising physician review and renew the CPA at least every two years.','The pharmacist treats the CPA as permanent after initial signatures and performs no later renewal.','CPA는 적어도 2년마다 review/renew한다. 초기 서명은 무기한 갱신 면제가 아니다.')
add('CDTM','A CPA specifies permitted laboratory monitoring linked to drug therapy without assigning an independent diagnostic function.','A CPA uses drug-monitoring authority as unrestricted authority for the pharmacist to make new independent diagnoses.','CDTM의 drug-related test evaluation와 독립 diagnosis 범위는 구별한다.')
add('CDTM','The parties arrange uninterrupted therapy and written patient notice before ending the collaboration.','The parties terminate the collaboration without informing patients who still depend on its prescribing and monitoring.','CPA 종료/비갱신에는 환자 통지와 치료 지속 계획이 필요하다.')
add('CDTM','The physician retains the original consent record and the pharmacist receives and retains the required copy.','The pharmacist uses a verbal statement that consent exists instead of maintaining the required retail referral/consent records.','Consent·referral의 원본/사본 보관 및 전달 경로가 있다. 말로 확인했다는 사실만으로 기록 요건을 대체하지 않는다.')

group('ACCESS','Standing orders and public-health access',2,['w5-b-2','w5-b-3','w5-b-4','w5-b-5','w3-d-18','w3-d-19','w3-d-20','w3-d-21'],
      'A patient requests a public-health pharmacy service in Massachusetts. Each option identifies the pathway being used; billing rules do not independently expand prescribing authority.',
      'M.G.L. c.94C §§19A–19B; Massachusetts EC and opioid-antagonist guidance; applicable FDA product status')
add('ACCESS','A pharmacist using the statewide emergency-contraception order assesses the person who will take the medication, in person or by telephone.','A pharmacist generates a statewide-order EC prescription for an absent user without the required patient assessment.','Statewide EC order의 patient assessment는 실제 사용자와 수행한다. OTC levonorgestrel의 제3자 구매와 구별한다.')
add('ACCESS','A pharmacist distinguishes prescription-only ulipristal from OTC levonorgestrel emergency contraception.','A pharmacist treats ulipristal as OTC solely because levonorgestrel emergency contraception is OTC.','응급피임이라는 목적이 같아도 제품의 prescription/OTC 경로는 다르다.')
add('ACCESS','A pharmacist explains that Opill is a daily norgestrel contraceptive rather than emergency contraception.','A pharmacist substitutes daily norgestrel Opill for requested emergency contraception solely because both prevent pregnancy.','성분·목적·사용경로가 다르므로 daily contraception과 EC를 자동 대체하지 않는다.')
add('ACCESS','A pharmacy separates OTC purchase eligibility from the prescription or order used for insurance billing.','A pharmacy tells every OTC naloxone purchaser that a prescription is legally required merely because insurance billing may use one.','OTC 적법 구매와 보험 reimbursement 서류는 별개의 판단이다.')
add('ACCESS','A pharmacist confirms the applicable standing order before using its patient-specific dispensing pathway.','A pharmacist treats a blank model standing-order template as a signed order authorizing dispensing.','Model template와 실제 적격 prescriber가 발행한 standing order는 다르다.')
add('ACCESS','A pharmacy dispenses an opioid-antagonist rescue kit with the required counseling and information material.','A pharmacy treats the rescue-kit label as replacing the applicable counseling and information-material obligations.','Opioid-antagonist dispensing의 label·counseling·pamphlet을 각각 충족한다.')
add('ACCESS','A pharmacy lacking requested opioid-antagonist stock refers the requester to the nearest available source.','A pharmacy lacking requested opioid-antagonist stock ends the encounter without the required access referral.','재고 미보유 시 해당 nearest-available-location referral를 수행한다.')
add('ACCESS','A pharmacist distinguishes permission to dispense under an EC standing order from a general license to prescribe any reproductive-health drug.','A pharmacist treats EC standing-order participation as authority to independently prescribe any reproductive-health drug.','Standing order의 지정 약물·평가·기록 범위가 남는다. 목적이 관련되어도 일반 처방권한이 아니다.')
add('ACCESS','A pharmacy maintains separate records for EC annual reporting and ordinary prescription dispensing.','A pharmacy assumes transmitting a controlled-drug PMP file automatically completes every EC reporting obligation.','별도 제도별 reporting을 구분한다. 서로 다른 시스템의 제출은 자동 대체되지 않는다.')
add('ACCESS','A pharmacist separates a plan’s extended contraception coverage from the pharmacist’s legally authorized prescribing modalities.','A pharmacist treats insurance coverage of a contraceptive injection as independent statutory permission to prescribe that injection.','보험의 covered product 범위와 pharmacist의 prescribing scope는 다르다.')

group('REMS','Product-specific restrictions and current labeling',2,['w3-b-8','w3-b-9','w3-b-11','w5-b-11','w5-b-12','w5-b-13'],
      'A pharmacist is reviewing product-specific dispensing restrictions as of October 26, 2026. The question does not apply any future iPLEDGE implementation before its effective date.',
      'Current FDA product-specific REMS/labeling; FDA clozapine REMS removal effective June 13, 2025')
add('REMS','A pharmacist does not require enrollment in the removed clozapine REMS as a dispensing prerequisite.','A pharmacist requires enrollment in the removed clozapine REMS before considering any clozapine prescription.','FDA가 clozapine REMS를 2025-06-13부로 제거했다. 폐지된 enrollment를 현재의 필수 dispensing gate로 가르치지 않는다.')
add('REMS','A pharmacist continues to consider clozapine’s label-based neutropenia monitoring and patient safety after REMS removal.','A pharmacist tells the patient that REMS removal also removed the need for label-based ANC monitoring.','REMS administrative requirement 제거와 neutropenia risk·label 기반 monitoring은 다르다.')
add('REMS','A pharmacist checks whether a drug has a current REMS rather than inferring enrollment requirements solely from a boxed warning.','A pharmacist assumes every boxed-warning drug automatically has mandatory patient and pharmacy REMS enrollment.','Boxed warning과 REMS 운영 프로그램은 동일하지 않다. 제품의 현행 조건을 확인한다.')
add('REMS','A certified pharmacy follows the applicable mifepristone REMS and valid-prescription requirements for its dispensing route.','A pharmacy treats state access protections as eliminating the federal mifepristone REMS certification requirement.','State access와 federal product-specific REMS는 함께 적용될 수 있으며 서로를 자동 면제하지 않는다.')
add('REMS','A pharmacist distinguishes fentanyl transdermal patches from transmucosal immediate-release fentanyl products.','A pharmacist applies a TIRF product’s outpatient enrollment pathway to every fentanyl patch solely because the ingredient matches.','Fentanyl 성분·CII라는 공통점만으로 TIRF 제형별 REMS를 patch에 복사하지 않는다.')
add('REMS','A pharmacy supplying Sublocade follows the certified delivery-to-healthcare-provider pathway rather than routine patient take-home injection.','A pharmacy hands Sublocade to the patient as a routine take-home injection solely because the prescription is valid.','Depot buprenorphine 제품의 REMS 공급 경로가 별도로 남는다. 유효 처방만으로 환자 직접교부가 정당화되지 않는다.')
add('REMS','A pharmacist distinguishes Brixadi weekly and monthly products before processing the ordered formulation.','A pharmacist exchanges Brixadi weekly and monthly products without clarification because both contain buprenorphine.','같은 성분이라도 formulation·regimen·제품 조건이 다르다. Generic 이름만으로 임의 교환하지 않는다.')
add('REMS','A pharmacist recognizes that the depot-injection REMS is not automatically the REMS of every buprenorphine patch or film.','A pharmacist blocks every buprenorphine patch or film unless the pharmacy is certified for the depot-injection REMS.','제품·route별 REMS를 성분 전체에 일괄 적용하지 않는다.')
add('REMS','A certified treatment setting follows Spravato’s supervised administration and monitoring pathway.','A pharmacy treats Spravato as an ordinary take-home nasal spray because nasal products are often self-administered.','Esketamine 제품의 지정 setting·supervision·monitoring 조건을 일반 nasal-route 관행으로 대체하지 않는다.')
add('REMS','A pharmacist distinguishes an FDA-approved change from its later implementation date before changing a REMS workflow.','A pharmacist applies every announced REMS change immediately even when the announcement specifies a future implementation date.','승인일·발표일·시행일은 다를 수 있다. 이 문항은 특정 미시행 workflow를 현행으로 확정하지 않는다.')

group('OUD','Indication, prescribing authority, and misuse assessment',2,['w2-a-5','w2-c-13','w2-c-14','w2-c-15','w3-b-4'],
      'A community pharmacist evaluates controlled-drug requests. The facts distinguish patient-specific prescriptions from stock orders and maintenance treatment from other indications.',
      '21 CFR 1306.04 and 1306.07; applicable Massachusetts scope and review duties')
add('OUD','A pharmacist distinguishes a legitimate methadone analgesia prescription from a methadone prescription written solely for OUD maintenance outside an OTP.','A pharmacist treats every methadone prescription as an ordinary retail OUD-maintenance prescription regardless of the treatment setting.','Methadone의 pain prescription과 OUD maintenance/OTP 경로는 다르다. 성분의 schedule만으로 치료 목적별 권한을 끝내지 않는다.')
add('OUD','A pharmacist confirms the prescriber’s current ordinary authority for buprenorphine rather than demanding a discontinued federal X-waiver identifier.','A pharmacist rejects an otherwise eligible buprenorphine OUD prescription solely because a discontinued federal X-waiver identifier is absent.','X-waiver 제거 후에도 current license/DEA·scope·legitimate purpose는 확인하지만 폐지된 identifier를 필수로 요구하지 않는다.')
add('OUD','A practitioner using the narrow federal emergency-dispensing exception evaluates its conditions and limited nonrenewable supply.','A practitioner uses the narrow federal emergency-dispensing exception to issue renewable retail methadone maintenance prescriptions.','Emergency dispensing 예외는 일반 OUD maintenance prescribing 허가가 아니다. Dispense와 prescribe를 구분한다.')
add('OUD','A pharmacist resolves material diversion concerns before dispensing even when the prescriber confirms sending the prescription.','A pharmacist ignores material diversion concerns solely because the prescriber confirms sending the prescription.','진정성 확인과 legitimate-purpose/corresponding responsibility는 별개의 판단이다. 서류가 진짜여도 중대한 우려를 검토한다.')
add('OUD','A pharmacy processes controlled stock for a practitioner through the lawful registrant-ordering route.','A pharmacy uses a patient prescription to supply a practitioner’s general office stock.','Prescription은 ultimate-user 치료를 위한 주문이다. 일반 office stock은 적법한 별도 distribution/ordering 경로를 사용한다.')
add('OUD','A pharmacist reviews an actual patient’s controlled-drug history for legitimate treatment-related care.','A pharmacist searches a neighbor’s controlled-drug history out of personal curiosity.','PMP 접근 자격이 호기심 검색 권한을 주는 것은 아니다. 허용된 목적과 환자 관계를 확인한다.')
add('OUD','A pharmacist treats the scheduled-drug classification, indication, and delivery route as separate checks for a depot product.','A pharmacist assumes Schedule III status alone resolves every depot product’s administration and shipping restriction.','Schedule, indication, exact product/route가 각각 추가 조건을 만들 수 있다.')
add('OUD','A pharmacist assesses a clinically significant sedative combination and records the intervention.','A pharmacist concludes that a low schedule number removes the need to assess a clinically significant sedative combination.','분류 단계가 낮다는 사실은 DUR·환자안전 의무를 없애지 않는다.')
add('OUD','A pharmacy distinguishes a patient-directed prescription transfer from a registrant-to-registrant transfer of stock bottles.','A pharmacy documents a stock-bottle distribution only as a patient prescription refill transfer.','처방정보 transfer와 약품 stock distribution는 다른 행위·서류·기록 체계이다.')
add('OUD','A pharmacist recognizes a state supply allowance as an upper limit, not permission to dispense more than the prescribed quantity.','A pharmacist increases a controlled prescription’s quantity to the state maximum without the required prescriber discussion.','법정 최대 공급량과 실제 처방자 authorization을 모두 충족해야 한다. 상한은 자동 지급량이 아니다.')

group('RX','Prescription authenticity and format',3,['w2-a-4','w2-a-5','w2-a-6','w2-a-7','w2-a-8','w2-a-10'],
      'A pharmacist is reviewing incoming prescriptions in Massachusetts. Any electronic-prescribing exception mentioned below is valid; it does not waive other controlled-drug requirements.',
      '21 CFR 1306.03–1306.05; 105 CMR 721; Policy 2020-15; 247 CMR 9.15')
add('RX','A practitioner dates a prescription on the actual issue date and separately provides an applicable earliest-fill instruction.','A practitioner replaces the actual issue date with a future date so that a later fill appears to be newly issued.','Actual issue date와 earliest-fill date는 다른 항목이다. 미래 발행일로 prescription clock를 재설정하지 않는다.')
add('RX','An authorized agent communicates a prescription already determined by the practitioner without independently changing its therapy.','An authorized agent independently selects a different drug and dose while transmitting the practitioner’s order.','전달 권한은 독립 임상 결정·처방권한이 아니다.')
add('RX','A pharmacist checks the practitioner’s current scope and registration rather than relying only on an identifier’s format.','A pharmacist accepts a properly formatted DEA identifier as sufficient proof of current authority for every schedule.','Identifier 형식은 현재 등록, 허용 schedules, profession scope 또는 실제 신원을 모두 증명하지 않는다.')
add('RX','A pharmacy receives an eligible paper prescription under a documented electronic-prescribing exception and applies the remaining rules.','A pharmacy treats a valid paper-format exception as permission to omit the remaining controlled-prescription requirements.','전자처방 예외는 format layer의 예외이다. 약물·수량·적법성·서명 등의 다른 요건을 자동으로 없애지 않는다.')
add('RX','A pharmacist distinguishes a scanned paper prescription from an originally generated EPCS.','A pharmacist treats a scanned paper prescription as original EPCS because the image is stored in the pharmacy database.','전자 저장과 original electronic prescription의 발행·전송은 다르다.')
add('RX','A pharmacist verifies a duplicate-looking EPCS and replacement paper order before any second dispensing.','A pharmacist counts an EPCS and its paper replacement as separate authorizations without checking whether one replaces the other.','Failover/replacement의 중복 조제를 방지하고 원 처방과 관계를 확인한다.')
add('RX','A pharmacist discusses a proposed federally controlled-drug prescription change with the prescriber or authorized agent where required.','A pharmacist increases a federally controlled prescription’s quantity solely to match a preferred insurance package size.','보험 선호 포장량만으로 controlled prescription의 quantity를 임의 변경할 수 없다.')
add('RX','A pharmacist obtains a new legally sufficient authorization when the requested change cannot be made under the permitted-change rules.','A pharmacist treats every new drug substitution as a clerical correction of the original controlled prescription.','허용된 보완/수정 범위와 새 적법한 prescription이 필요한 변경을 구별한다.')
add('RX','A pharmacy distinguishes an inpatient immediate-administration order from an outpatient discharge prescription.','A pharmacy applies an inpatient-order exception to an outpatient discharge prescription solely because the prescriber works at a hospital.','기관의 주소·처방자 소속이 아니라 실제 order와 dispensing setting을 구분한다.')
add('RX','A pharmacist resolves credible forgery concerns before releasing a medication.','A pharmacist treats a successful insurance adjudication as resolving credible prescription-forgery concerns.','보험 지급 결정은 처방의 authenticity 판단을 대체하지 않는다.')

group('EPCS','First-fill transfer versus refill transfer',3,['w2-c-4','w2-c-5','w2-c-6','w2-c-7'],
      'Two Massachusetts retail pharmacies receive requests to move prescriptions. Both have appropriate registrations; the options specify original format, prior dispensing, and the intended transfer method.',
      '21 CFR 1306.08(e)–(h), 1306.25; Policy 2023-10; 247 CMR 9.14')
add('EPCS','At the patient’s request, pharmacists transfer a never-filled CII EPCS once, electronically and without altering its contents.','At the patient’s request, pharmacists print and fax a never-filled CII EPCS as the permitted electronic first-fill transfer.','허용된 initial EPCS transfer는 electronic 상태·unaltered contents·일회 경로이다. Print/fax로 바꾸면 같은 허용 경로가 아니다.')
add('EPCS','A pharmacy explains that an unfilled paper alprazolam prescription does not become transferable EPCS after data entry.','A pharmacy transfers an unfilled paper alprazolam prescription as EPCS after entering it into the dispensing computer.','Original paper/fax/oral II–V는 database에 입력해도 original EPCS로 변환되지 않는다.')
add('EPCS','Both pharmacists link required first-fill transfer details to the electronic prescription record.','Both pharmacies retain only a courier receipt and omit pharmacist and pharmacy transfer information.','Prescription information transfer에는 pharmacy·DEA·pharmacist·date 등 지정 기록을 남긴다. 물리적 운송 영수증과 다르다.')
add('EPCS','A pharmacy retains the applicable original-EPCS transfer records for at least two years from the transfer date.','A pharmacy discards the original-EPCS transfer record as soon as the first supply is dispensed.','Initial EPCS transfer records의 기산점은 transfer date이고 최소 2년 보존한다.')
add('EPCS','A never-filled electronic Schedule III prescription moves with its associated authorized refills in a valid initial transfer.','A receiving pharmacy assumes the initial transfer creates five new refills even when the prescriber authorized only one.','Associated refills를 보존하여 옮기는 것이지 법정 최대를 새 authorization으로 생성하지 않는다.')
add('EPCS','A pharmacist distinguishes a partially dispensed CII prescription from a never-filled CII EPCS.','A pharmacist uses the never-filled EPCS rule to move an already partially dispensed CII remainder.','이미 partial dispensing이 있으면 never-filled 조건이 성립하지 않는다.')
add('EPCS','Pharmacies sharing a qualifying real-time database apply the III–V refill-transfer exception within remaining authorizations.','Pharmacies apply the III–V shared-database refill exception solely because they use the same chain logo.','같은 chain/벤더라는 표면 정보가 qualifying real-time online database를 입증하지 않는다.')
add('EPCS','Two independent pharmacies communicate an eligible Schedule IV refill transfer directly between licensed pharmacists.','Two independent pharmacies conduct a Schedule IV refill transfer solely between their certified technicians.','Federal III–V refill transfer의 licensed-pharmacist communication과 MA VI technician 경로는 다르다.')
add('EPCS','A pharmacy timely transfers an eligible Schedule VI prescription requested by the patient without a transfer fee.','A pharmacy charges the patient a processing fee before transferring an otherwise eligible Schedule VI prescription.','MA는 timely transfer와 transfer fee 금지를 규정한다.')
add('EPCS','A pharmacy keeps the original issue date when receiving a valid refill transfer.','A receiving pharmacy uses the transfer date as a new issue date to extend the prescription’s refill life.','Transfer는 original prescription의 수명을 다시 시작하지 않는다.')

group('CII','CII format and supply decisions',3,['w2-b-1','w2-b-2','w2-b-3','w2-b-4','w2-b-5'],
      'A Massachusetts pharmacist evaluates Schedule II dispensing. Assume clinical appropriateness and valid prescriber authority, but do not assume an unstated exception to format, validity, or supply limits.',
      'M.G.L. c.94C §23; Policy 2024-05; 21 CFR 1306.11–1306.12; 21 CFR 290.10')
add('CII','A pharmacist treats an authorized CII partial remainder as distinct from a refill.','A pharmacist honors the prescriber’s notation of two refills on a CII prescription as routine refill permission.','CII refill은 금지된다. 적법한 partial filling과 별도 새 prescription을 refill과 혼동하지 않는다.')
add('CII','A pharmacist separately checks a 90-day eligible supply and the Massachusetts 30-day prescription-validity period.','A pharmacist treats permission for a 90-day supply as making the CII prescription initially fillable for 90 days.','Supply duration과 issue-date validity는 다른 숫자이다.')
add('CII','A pharmacist applies the eligible non-opioid CII/III 90-day supply category without adding an obsolete ADHD-only diagnosis requirement.','A pharmacist limits every eligible non-opioid CII prescription to 30 days unless an ADHD or narcolepsy diagnosis is documented.','Policy 2024-05의 non-opioid 범주는 예전 ADHD/narcolepsy-only 확인 방식에 묶이지 않는다.')
add('CII','A pharmacist assesses a testosterone prescription under the applicable non-opioid CIII supply category.','A pharmacist treats every testosterone prescription as restricted to 30 days solely because it is Schedule III.','Testosterone은 non-opioid CIII로 해당 90일 범주를 검토한다. Prescribed quantity 및 다른 조건은 남는다.')
add('CII','A pharmacist distinguishes buprenorphine prescribed for OUD from an ordinary opioid-pain prescription when applying the supply categories.','A pharmacist applies the OUD supply category to any opioid-pain prescription solely because an opioid is involved.','Indication별 OUD allowance와 일반 opioid pain을 구별한다.')
add('CII','A pharmacist checks whether the emergency oral CII conditions actually exist rather than treating every closed office as an emergency.','A pharmacist treats the prescriber’s office being closed as sufficient by itself for every emergency oral CII.','Federal emergency definition에는 즉시 필요, 적절한 대체치료 없음, 사전 written Rx 제공의 합리적 불가 등 조건이 있다.')
add('CII','The prescribing practitioner directly gives the pharmacist an emergency oral CII authorization limited to the emergency period.','The pharmacy routinely dispenses a fixed seven-day supply for every emergency oral CII without considering the emergency period.','최초 quantity는 emergency period에 적절한 양이다. Follow-up 기한 7일을 자동 supply로 바꾸지 않는다.')
add('CII','A pharmacist obtains and links the federal emergency follow-up prescription without treating it as a second supply authorization.','A pharmacist dispenses a second identical supply when the emergency follow-up prescription arrives.','Follow-up은 최초 emergency quantity를 문서화한다. Duplicate dispensing를 허용하는 새 처방으로 취급하지 않는다.')
add('CII','A pharmacist identifies a qualifying hospice patient’s CII narcotic fax as a possible federal fax-as-original pathway.','A pharmacist treats a CII nonnarcotic fax for any hospice patient as covered by the hospice-narcotic exception.','Hospice fax exception의 narcotic 조건을 유지한다. LTCF의 별도 CII 경로와 섞지 않는다.')
add('CII','A central-fill service does not use the retail pharmacy’s emergency-oral CII receipt pathway.','A central-fill service accepts emergency oral CII authorizations under the same rule used by a retail pharmacist.','21 CFR 1306.11(d)의 emergency oral CII는 central-fill pharmacy가 처리할 수 있는 경로가 아니다.')

group('PARTIAL','Partial-fill route and clock selection',3,['w2-b-6','w2-b-7','w2-b-8','w2-b-9','w2-c-2'],
      'The pharmacist is checking partial-fill records. The option states the reason for the partial fill; a shortage is not retroactively reclassified as a patient request.',
      '21 CFR 1306.13 and 1306.23; M.G.L. c.94C §18(d¾); 105 CMR 721.055')
add('PARTIAL','For a stock-shortage CII partial, the pharmacist tracks the 72-hour remainder period from the first partial filling.','For a stock-shortage CII partial, the pharmacist starts a new 72-hour period when the replacement stock arrives.','Shortage remainder의 시계는 first partial filling에서 시작한다. 입고일로 재설정하지 않는다.')
add('PARTIAL','After the shortage remainder cannot be completed within 72 hours, the pharmacist notifies the prescriber and requires a new prescription for later supply.','After 72 hours, the pharmacist supplies the shortage remainder because the original prescription is still within its ordinary 30-day validity.','일반 validity가 남아 있어도 shortage partial의 72시간 제한을 우회하지 못한다.')
add('PARTIAL','For a valid patient-requested non-emergency CII partial, the pharmacist measures the 30-day federal remainder limit from the issue date.','For a valid patient-requested non-emergency CII partial, the pharmacist measures 30 days from each later partial dispensing.','Requested partial의 기본 remainder limit은 prescription written/issue date 기준이다.')
add('PARTIAL','A pharmacy documents the patient’s actual request and partial quantity in the applicable CII record.','A pharmacy converts an undocumented stock shortage into a patient-requested partial after its shortage clock expires.','실제 request와 기록이 필요하다. 편리한 기한을 얻기 위한 사후 분류 변경이 아니다.')
add('PARTIAL','A pharmacist keeps the combined quantities of all partial fills within the total authorized quantity.','A pharmacist counts each partial fill as a new full quantity authorization.','Partial transaction 수와 새 prescription/refill authorization은 다르다. 총량을 추적한다.')
add('PARTIAL','A Massachusetts pharmacy completes a qualifying patient-requested CII remainder at the same pharmacy that supplied the initial partial.','A Massachusetts pharmacy directs a different pharmacy to finish the patient-requested CII remainder as a routine refill transfer.','MA의 해당 patient-requested CII remainder에는 same-pharmacy 조건이 있다.')
add('PARTIAL','A parent or legal guardian requests a permitted partial fill for a minor patient under the federal rule.','An unrelated adult with no qualifying authority substitutes a purported partial-fill request for the minor patient’s parent or guardian.','Federal requested-partial 경로의 요청자는 patient, minor의 parent/legal guardian 또는 조문상 적격 caregiver/practitioner이다.')
add('PARTIAL','For an emergency oral CII requested partial, the pharmacist distinguishes the 72-hour period measured from issuance from the non-emergency 30-day period.','For an emergency oral CII requested partial, the pharmacist applies the non-emergency 30-day remainder limit.','Emergency oral requested partial의 연방 remainder는 issue 후 72시간이다. 일반 requested written/EPCS의 30일과 다르다.')
add('PARTIAL','A pharmacist records a Schedule IV partial with proper quantity accounting within the original six-month period.','A pharmacist applies the CII stock-shortage 72-hour rule as the universal deadline for every Schedule IV partial.','III–V partial의 수량·기록·6개월 기준과 CII shortage를 구별한다.')
add('PARTIAL','A pharmacist separately records the refill number and partial-fill indicator for a split dispensing.','A pharmacist automatically increments the authorized refill number for every partial transaction regardless of the quantity represented.','거래 횟수, partial indicator, authorized refill count는 별도 필드와 개념이다.')

group('REFILL','Refill authorization and transfer records',3,['w2-c-1','w2-c-2','w2-c-5','w2-c-7'],
      'A community pharmacist reconciles Schedule III–VI refill histories. No emergency-continuity exception is invoked in these entries.',
      '21 CFR 1306.22–1306.25; 247 CMR 9.04(12)–(13), 9.14')
add('REFILL','A pharmacist counts the original Schedule IV dispensing separately from the five-refill legal maximum.','A pharmacist treats the legal maximum of five refills as permission for five additional fills when the prescriber authorized none.','법정 최대와 실제 prescriber authorization은 다르며 original fill은 refill이 아니다.')
add('REFILL','A pharmacist rejects a Schedule III refill after the six-month issue-date limit even when a refill remains on the record.','A pharmacist fills a Schedule III refill after the six-month issue-date limit because the unused refill count is positive.','잔여 횟수와 기간을 함께 충족한다. 남은 authorization이 기간을 연장하지 않는다.')
add('REFILL','A pharmacist applies Massachusetts’s six-month and five-refill limits to an ordinary Schedule V prescription.','A pharmacist applies the Schedule VI one-year period to an ordinary Schedule V prescription.','MA Schedule V에는 6개월·5refill 제한이 있으며 VI framework와 다르다.')
add('REFILL','A pharmacist checks remaining prescriber authorization before refilling a Schedule VI prescription within one year.','A pharmacist treats an unexpired Schedule VI prescription as allowing unlimited refills without remaining prescriber authorization.','VI의 1년 validity가 unlimited authorization을 주는 것은 아니다.')
add('REFILL','A pharmacist records refill date, quantity, and dispensing pharmacist identification.','A pharmacist uses only the insurance claim number as the complete refill record.','Refill 기록의 date/amount/pharmacist identification를 유지한다. 보험 claim identifier만으로 대체되지 않는다.')
add('REFILL','A pharmacist preserves the original issue date and remaining refills when transferring a prescription.','A pharmacist replenishes the original number of refills when the prescription moves to a new pharmacy.','Transfer는 이미 사용한 authorization을 복원하거나 새로 발행하는 절차가 아니다.')
add('REFILL','A receiving pharmacy obtains the original issue and dispensing history required for an eligible III–V refill transfer.','A receiving pharmacy accepts only drug name and today’s date as the complete III–V refill-transfer record.','Transfer에는 original date, authorized/remaining refills, pharmacy/pharmacist 정보 등 지정 요소가 필요하다.')
add('REFILL','Both pharmacies preserve the applicable III–V refill-transfer records for at least two years from the last refill.','Both pharmacies use two years from the first transfer as the only retention endpoint even when a later refill extends the required period.','Refill transfer records의 기산점은 last refill이다. Initial unfilled EPCS transfer-date 기준과 다르다.')
add('REFILL','An ordinary technician requests an unchanged authorized refill and refers a newly proposed dose change to the pharmacist.','An ordinary technician processes a newly proposed dose change as an unchanged refill authorization.','변경 없는 refill 수신과 새로운 drug-therapy clarification/modification는 서로 다른 scope이다.')
add('REFILL','A pharmacist obtains a new prescription when continuation exceeds the original III–IV six-month or refill authorization limits.','A pharmacist changes the original issue date to keep the existing III–IV prescription active beyond its legal limits.','후속 authorization에도 원 처방의 기간·횟수 한계가 적용된다. Issue date를 고쳐 한계를 없애지 않는다.')

group('LABEL','Labeling and product substitution',3,['w3-a-1','w3-a-2','w3-a-3','w3-a-4','w3-a-6','w3-a-7','w3-a-8','w3-a-9','w3-a-10'],
      'A Massachusetts pharmacist reviews outpatient labels and proposed substitutions. Assume the prescriber’s intended ingredient, strength, dosage form, and route are known.',
      'M.G.L. c.94C §21; c.112 §§12D,12EE; 247 CMR 9.04–9.05; FDA Orange/Purple Book framework')
add('LABEL','A pharmacist identifies the actually dispensed generic and manufacturer on the applicable interchange label.','A pharmacist labels only the originally prescribed brand when a different interchangeable product is actually dispensed.','환자 label은 실제 교부된 제품을 식별해야 한다. 원래 brand만 남겨 제품 변경이 사라지게 하지 않는다.')
add('LABEL','A pharmacist evaluates an exact product’s therapeutic-equivalence relationship rather than relying only on the active ingredient name.','A pharmacist substitutes an extended-release product for an immediate-release prescription solely because the ingredient and milligrams match.','Ingredient뿐 아니라 strength/form/route/TE relationship 및 처방 의도를 확인한다. IR/ER는 자동 대체가 아니다.')
add('LABEL','A pharmacist uses the relevant FDA Purple Book information when evaluating biological interchangeability.','A pharmacist treats any approved biosimilar as automatically designated interchangeable for pharmacy substitution.','Biosimilarity와 interchangeability를 구별하고 MA biological substitution 조건을 함께 적용한다.')
add('LABEL','A pharmacist gives the patient the required written notification after an eligible biological substitution.','A pharmacist treats a private note to the inventory department as the required patient notification after biological substitution.','환자 written notification과 내부 재고 기록은 다른 행위이다.')
add('LABEL','A pharmacist preserves the actual prescribing practitioner in internal verification records while using an eligible protected-care practice name on the patient label.','A pharmacist removes the actual practitioner from all internal records when an eligible practice name is used on the patient label.','환자용 protected-care label 예외와 원 prescription/권한확인/audit record를 구별한다.')
add('LABEL','A pharmacist applies a shorter product-specific in-use period when it is more limiting than the general label-date ceiling.','A pharmacist assigns every dispensed medication a full year of stability without considering reconstitution or product-specific limits.','Manufacturer expiry, BUD/in-use period, 일반 date ceiling 중 실제 적용되는 더 짧은 제한을 지킨다.')
add('LABEL','During a qualifying medical emergency, a pharmacist documents the date, hour, and nature of the event and obtains written purchaser acceptance for the permitted substitution.','During a qualifying medical emergency, a pharmacist uses verbal purchaser agreement alone for the permitted substitution despite the required written acceptance.','Emergency interchange의 별도 기록과 purchaser written acceptance 조건을 충족한다.')
add('LABEL','A pharmacist distinguishes an authorized generic marketed under the brand NDA from a separate ANDA product.','A pharmacist concludes that any product sold by the same company is the authorized generic of the prescribed brand.','Regulatory product relationship을 확인한다. 같은 회사라는 이유만으로 authorized generic을 추정하지 않는다.')
add('LABEL','A pharmacist recognizes that a required federal patient-to-patient transfer warning does not prohibit a lawful pharmacy-to-pharmacy prescription-information transfer.','A pharmacist refuses a lawful prescription-information transfer solely because the patient label contains the federal transfer warning.','Label의 다른 사람에게 약물 양도 금지와 pharmacist prescription-information transfer는 다른 의미이다.')
add('LABEL','A pharmacy checks an applicable large-print request in characters per inch rather than assuming it means a ten-point font.','A pharmacy treats the statutory ten-characters-per-inch wording as an automatic requirement for ten-point type.','Characters-per-inch와 typographic point는 다른 단위이다. 환자 방향 표시의 규정 문구를 정확히 읽는다.')

group('PACK','Packaging and return pathways',3,['w3-a-11','w3-a-12','w3-a-13','w3-a-14','w3-a-15','w3-a-16','return-pathways'],
      'A pharmacist reviews packaging requests and returned medications. No controlled-drug multi-drug-packaging conflict is being adjudicated; any multi-drug examples use Schedule VI products only.',
      'PPPA; 16 CFR 1700.14; 247 CMR 9.01,9.07–9.08,9.13; applicable packaging policy')
add('PACK','A pharmacist documents a patient’s actual request for non-child-resistant packaging before using that requested pathway.','A pharmacist treats advanced age alone as an automatic request for non-child-resistant packaging.','고령 자체와 환자의 적법한 request는 다르다. 요청의 범위를 확인한다.')
add('PACK','A pharmacist limits a prescriber’s non-child-resistant request to the prescription it concerns.','A pharmacist extends a prescriber’s single-prescription non-child-resistant request to all of that patient’s future prescriptions.','Prescriber request의 특정 prescription 범위와 patient blanket request를 구별한다.')
add('PACK','A pharmacist checks that sublingual nitroglycerin meets its specific packaging exemption.','A pharmacist extends the sublingual-nitroglycerin exemption to every oral nitrate formulation.','Exemption은 특정 제형/제품 조건이다. 같은 계열 전체에 확대하지 않는다.')
add('PACK','A pharmacist applies the prednisone-tablet exemption only when the package total is within its 105 mg limit and other conditions are met.','A pharmacist applies the prednisone-tablet exemption to any package because every tablet is below 105 mg.','Threshold는 tablet당이 아니라 package total이다. 제형·조합 조건도 남는다.')
add('PACK','A pharmacist evaluates child resistance separately from evidence that a package has already been opened.','A pharmacist treats tamper-evident wrapping as proof that child-resistant packaging requirements are satisfied.','Tamper-evident와 child-resistant는 다른 성능이다.')
add('PACK','A pharmacy prepares a Schedule VI multi-drug dose package containing scheduled medicines within the applicable 60-day limit.','A pharmacy includes PRN Schedule VI doses in a multi-drug dose package as though they were fixed scheduled doses.','Multi-drug packaging에서 scheduled use와 PRN을 구별한다. Schedule VI라는 사실이 PRN 제한을 없애지 않는다.')
add('PACK','A pharmacy repackages its own returned compliance package for the same patient after a documented therapy change.','A pharmacy uses tablets removed from one patient’s compliance package as dispensing stock for another patient.','동일 pharmacy·동일 patient의 제한적 repack 경로와 일반 재판매 재고를 구별한다.')
add('PACK','A pharmacy keeps a never-dispensed return-to-stock drug in an appropriate labeled container, not the manufacturer’s bottle.','A pharmacy pours a never-dispensed return-to-stock drug into the manufacturer’s stock bottle after checking the tablet appearance.','MA return-to-stock는 manufacturer bottle로 되붓지 않으며 지정 label정보와 원래 expiry를 유지한다.')
add('PACK','A pharmacy accepts a medication it dispensed in error and quarantines it for proper disposal.','A pharmacy accepts a medication it dispensed in error and immediately returns it to saleable inventory.','오조제/의심결함 반환 수용 의무와 inventory 재사용 허용은 다르다.')
add('PACK','A pharmacy excludes returned-to-stock tablets from a recall only after confirming that their lot is not affected.','A pharmacy continues dispensing returned-to-stock tablets of unknown lot because they are no longer in the recalled manufacturer’s bottle.','용기를 바꾸어 lot를 모르게 되었다고 recall 대상 가능성이 사라지지 않는다.')

group('PMP','MassPAT, identifiers, and data reporting',3,['w2-c-8','w2-c-9','w2-c-10','w2-c-11','w2-c-12','w2-a-2'],
      'A Massachusetts pharmacy reviews PMP-related obligations. Distinguish account registration, clinical queries, dispensing-data submission, and identification at pickup.',
      '105 CMR 700.012; 247 CMR 9.04(14),9.15; Massachusetts PMP dispenser guidance')
add('PMP','A pharmacist dispensing reportable drugs maintains the required PMP account and login information.','A pharmacist treats the pharmacy’s automated reporting software as replacing the pharmacist’s required PMP account.','Pharmacist account 유지와 pharmacy data submission는 별개이다.')
add('PMP','A pharmacy separately transmits required dispensing data after the pharmacist clinically reviews a patient’s history.','A pharmacy treats one patient-history query as completing the dispensing-data submission for that prescription.','조회는 보고가 아니다. 각각의 해당 의무를 이행한다.')
add('PMP','A pharmacist recognizes gabapentin as Massachusetts Schedule VI with additional PMP obligations.','A pharmacist treats gabapentin’s PMP reporting designation as proof that it is federally Schedule V.','Additional Drug reporting 지정과 federal scheduling는 다른 제도이다.')
add('PMP','A pharmacist obtains the applicable identifier of the actual agent collecting a reportable prescription.','A pharmacist substitutes an absent patient’s stored identifier without evaluating the actual collecting agent requirement.','Pickup의 ultimate user 또는 agent에 대한 실제 customer identifier 요건을 확인한다.')
add('PMP','When the serious-hardship exception applies, the pharmacist documents the reason and obtains the required printed name/address and signature.','When the serious-hardship exception applies, the pharmacy records only a verbal nickname and no required name/address/signature.','Hardship exception에는 사유 기록과 지정 수령자 기록이 필요하다. 전면적인 기록 면제가 아니다.')
add('PMP','A pharmacy distinguishes correcting an erroneous dispensing submission from altering the original clinical prescription.','A pharmacy treats every PMP submission correction as authority to alter the prescriber’s actual directions.','데이터 정정과 clinical prescription modification의 권한은 다르다.')
add('PMP','A pharmacist preserves the original refill number and uses the applicable partial indicator for a split dispensing.','A pharmacy reports every split dispensing as an independently authorized new refill.','PMP field reporting에서 partial과 refill authorization을 구분한다.')
add('PMP','A pharmacist keeps a patient-care query within the permitted purpose and access role.','A pharmacist shares PMP login credentials with a coworker to avoid that coworker’s required access controls.','허용된 사용자·역할별 접근을 유지한다. 계정 보유가 credential 공유 허가가 아니다.')
add('PMP','A pharmacist distinguishes a prescriber’s mandatory-query trigger from the pharmacy’s duty to submit dispensing data.','A pharmacy assumes drugs outside one prescriber-query trigger are automatically excluded from dispensing reporting.','Query trigger와 reportable-drug 범위는 서로 다를 수 있다.')
add('PMP','A pharmacist completes DUR and authenticity review separately from the PMP query.','A pharmacist treats a clear PMP report as proof that allergies, dose, and prescription authenticity need no further review.','PMP는 review의 자료 중 하나이다. DUR와 authenticity의 모든 요소를 대체하지 않는다.')

group('INVENTORY','Physical inventory and controlled-stock accountability',4,['w2-d-5','w2-d-6','w2-d-7','w2-d-8','w4-a-5'],
      'The pharmacist is reviewing controlled-stock accountability at a Massachusetts retail pharmacy. Federal inventory and state perpetual-reconciliation duties are separate.',
      '21 CFR 1304.04,1304.11; 247 CMR 9.16,9.21')
add('INVENTORY','A newly operating registrant records a zero initial controlled-substance inventory when no stock is on hand.','A newly operating registrant omits an initial inventory because no controlled stock is on hand.','Initial inventory는 재고 0도 기록한다. 약이 없다는 사실과 기록 의무 없음은 다르다.')
add('INVENTORY','A registrant takes the next federal inventory within two years of the previous inventory.','A registrant delays the next federal inventory past two years to align it with a convenient year-end count.','Biennial inventory의 최대 간격은 2년이다. 편리한 달력 기준으로 초과하지 않는다.')
add('INVENTORY','A pharmacist identifies whether an inventory was taken at opening or close of business.','A pharmacist omits the opening-or-closing designation because the calendar date is recorded.','날짜와 opening/closing designation를 함께 기록해야 수량의 시점을 식별할 수 있다.')
add('INVENTORY','A pharmacist exactly counts or measures opened Schedule II stock for the federal inventory.','A pharmacist estimates opened Schedule II stock because the bottle originally held fewer than 1,000 tablets.','CII는 exact count/measure이다. III–V의 특정 estimate rule를 CII에 옮기지 않는다.')
add('INVENTORY','A pharmacist exactly counts an opened Schedule IV container holding more than 1,000 tablets for the federal inventory.','A pharmacist estimates that opened Schedule IV container merely because it is below Schedule II.','III–V라도 container가 1,000 tablets/capsules를 초과하면 exact count를 요구한다.')
add('INVENTORY','The pharmacy performs CII physical reconciliation at least every ten days in addition to the federal inventory.','The pharmacy skips CII reconciliation until the next biennial inventory because perpetual balances are updated electronically.','MA CII 최소 10일 physical reconciliation과 federal biennial inventory는 대체 관계가 아니다.')
add('INVENTORY','The MOR investigates a physical shortage before making an accountable inventory adjustment.','A certified technician zeros out an unexplained shortage as routine data entry.','원인 조사·적격 adjustment 권한과 routine entry를 구별한다.')
add('INVENTORY','Expired controlled stock awaiting lawful disposition remains secured and accounted for.','Expired controlled stock is removed from all accountability records before it is actually disposed of or transferred.','Expiration은 possession/security/inventory 책임의 종료 사건이 아니다.')
add('INVENTORY','A pharmacy preserves known or suspected theft-related surveillance for the longer applicable retention period.','A pharmacy overwrites suspected-diversion footage after the ordinary 14-day period without preserving the incident evidence.','일반 영상 최소 14일과 theft/diversion 관련 최소 2년을 구별한다.')
add('INVENTORY','A pharmacist confirms actual receipts before adding a controlled shipment to the perpetual balance.','A pharmacist records the entire ordered quantity as received before the shipment is delivered and checked.','Order·shipment·receipt는 다른 사건이다. Actual on-hand accountability를 유지한다.')

group('ORDER','Controlled-drug ordering and distribution',4,['w2-d-1','w2-d-2','w2-d-3','w2-d-4'],
      'A pharmacy purchases or transfers controlled stock between registrants. These are stock transactions, not patient prescription-information transfers.',
      '21 CFR 1305; 21 CFR 1307.11')
add('ORDER','An eligible Schedule II stock purchase uses a properly executed Form 222 or qualifying CSOS order.','An ordinary Schedule II stock purchase uses a patient’s prescription as its sole stock-ordering document.','해당 registrant간 II stock ordering과 ultimate-user prescription은 다른 경로이다.')
add('ORDER','A purchaser retains the required copy of the executed single-sheet Form 222 before sending the original to the supplier.','A purchaser follows obsolete triplicate-copy handling without retaining the required current executed-order record.','현재 single-sheet 체계와 required purchaser/supplier records를 따른다. 구형 색상·3장 방식만으로 처리하지 않는다.')
add('ORDER','A supplier completes eligible partial Form 222 shipments within 60 days of the order date.','A supplier restarts a 60-day completion period with each partial shipment on the same Form 222.','Order fulfillment 시계는 original order date 기준이다. Patient partial-fill 시계와도 다르다.')
add('ORDER','A registrant grants a properly executed power of attorney before another person signs eligible stock orders.','A new pharmacist signs any pharmacy Form 222 solely because pharmacist licensure itself grants ordering power of attorney.','Pharmacist title와 특정 registrant의 POA는 다르다.')
add('ORDER','A CSOS signer uses the signer’s own valid digital certificate and authorized credentials.','A departing CSOS signer leaves personal signing credentials for coworkers to continue using.','Certificate·POA·registration의 유효성과 개별 signing controls를 유지한다.')
add('ORDER','The purchaser records actual quantities and dates received against a partially fulfilled order.','The purchaser treats the ordered quantity as the final receipt record even when only part was delivered.','주문량과 실제 receipt를 구분하여 각 partial shipment를 추적한다.')
add('ORDER','A pharmacy calculates the practitioner-distribution exception using applicable controlled-substance dosage units.','A pharmacy calculates the practitioner-distribution exception using dollars of pharmacy revenue.','DEA 5%의 분자는 해당 distributed dosage units, 분모는 해당 annual distributed+dispensed units이다. 매출액 비율이 아니다.')
add('ORDER','A pharmacy expecting to exceed the applicable five-percent distribution limit obtains the appropriate registration rather than waiting for year-end.','A pharmacy knowingly exceeds the distribution limit and waits until year-end to decide whether registration was needed.','초과가 합리적으로 예상되면 적절한 registration을 확보해야 한다. 사후 계산만으로 허용되지 않는다.')
add('ORDER','A pharmacy checks both the recipient’s registration and the required ordering records before an eligible controlled-stock transfer.','A pharmacy considers the recipient’s familiar business name sufficient and omits the recipient-authority check.','등록된 상대방의 authorized activity/schedules와 transaction records를 확인한다.')
add('ORDER','A pharmacy distinguishes DEA Form 106 loss reporting from Form 222 ordering and Form 41 destruction records.','A pharmacy uses a Form 222 purchase record as the complete substitute for a reportable controlled-substance loss.','각 DEA 서류는 목적이 다르며 서로 대체하지 않는다.')

group('DISPOSE','Collection, returns, and destruction',4,['w2-d-13','w2-d-14','w2-d-15','w2-d-16','w5-a-19'],
      'An authorized pharmacy is choosing a disposal route. Distinguish pharmacy-owned inventory, ultimate-user medication, sealed collection liners, and recalled product.',
      '21 CFR 1317; applicable DEA registration and state disposal requirements')
add('DISPOSE','A pharmacy sends its expired controlled inventory to an appropriately authorized reverse distributor through the lawful route.','A pharmacy places its own expired controlled inventory in a receptacle designated for ultimate-user collection.','Pharmacy inventory disposal와 ultimate-user collection은 다른 경로이다.')
add('DISPOSE','An authorized collector keeps a sealed inner liner closed while arranging lawful transfer or destruction.','An authorized collector reopens a sealed inner liner to count recoverable tablets.','Sealed collection liner는 수거된 개별약을 다시 분류·회수하기 위해 열지 않는다.')
add('DISPOSE','A pharmacy obtains the collector authorization required for its chosen controlled-substance collection service.','A pharmacy assumes ordinary dispensing registration alone authorizes every controlled-substance collection program.','Dispensing registration과 collector authorization을 구별한다.')
add('DISPOSE','A patient uses an eligible authorized mail-back package and its designated return route.','A patient mails loose controlled tablets in an ordinary envelope to a pharmacy that is not the designated mail-back collector.','Mail-back에는 적격 package·collector·운송경로 조건이 있다. 일반 우편 봉투가 그 경로를 대신하지 않는다.')
add('DISPOSE','A registrant uses a compliant destruction method that renders controlled substances non-retrievable.','A registrant treats disposal in an ordinary trash container as proof that controlled substances are non-retrievable.','Non-retrievable라는 결과와 규정상 witness/record/보안 등을 충족해야 한다. 단순 버리기와 다르다.')
add('DISPOSE','A pharmacy maintains appropriate accountability when stock is quarantined pending reverse distribution.','A pharmacy removes quarantined stock from all controlled-drug records while it remains in the pharmacy.','Quarantine/disposition 대기는 여전히 possession과 accountability의 대상이다.')
add('DISPOSE','A pharmacy distinguishes an authorized ultimate-user recall return from routine restocking of patient-returned medication.','A pharmacy treats a recall return as permission to re-dispense the returned medication to another patient.','반환을 받을 수 있는 사유와 재판매 허용은 다르다.')
add('DISPOSE','The collector follows the employee-witness and liner-handling controls applicable to the collection setting.','A collector substitutes an unsupervised public volunteer for the employees required to control a sealed collection liner.','Collector/setting별 적격 personnel과 handling safeguards를 따른다. 일반 봉사자의 편의가 요건을 대체하지 않는다.')
add('DISPOSE','A pharmacist evaluates hazardous-waste requirements separately from controlled-substance disposal requirements.','A pharmacist assumes compliance with DEA destruction rules automatically satisfies every hazardous-waste rule.','HD/waste와 controlled schedules는 다른 분류이므로 적용되는 두 체계를 모두 검토한다.')
add('DISPOSE','A pharmacy uses the stock-return ordering and record requirements applicable to the schedule and transaction.','A pharmacy treats a Schedule II stock return as exempt from every ordering record solely because no new sale occurs.','Return/recall registrant transaction에도 해당 Form 222/CSOS 및 기록 요건이 적용될 수 있다. Sale 여부만으로 전체 면제를 만들지 않는다.')

group('STORAGE','Cold chain and delivery decisions',4,['w4-a-1','w4-a-2','w4-a-8','w4-a-9','w4-a-10','w4-a-11','w6-a-14'],
      'A pharmacy reviews receiving, storage, and shipment events. Product-specific approved storage instructions take precedence over an unsupported assumption about stability.',
      '247 CMR 9.02,9.19,9.22; Policy 2020-05; medication-shipping advisory; USPS Publication 52 §453')
add('STORAGE','A pharmacy quarantines a temperature-excursion product until the applicable stability and disposition assessment is complete.','A pharmacy returns an excursion product to saleable stock solely because its temperature has returned to normal.','정상 온도 복귀가 과거 excursion를 없애지 않는다. 시간·온도·제품 안정성의 근거로 판단한다.')
add('STORAGE','A pharmacy follows a product’s specific frozen-storage instructions rather than substituting a general refrigerator range.','A pharmacy stores every temperature-sensitive drug at 2–8°C even when the product requires a different range.','일반 냉장 범위와 제품별 더 구체적인 보관 조건을 구별한다.')
add('STORAGE','A pharmacy uses an appropriate medication-storage unit and keeps food and drinks elsewhere.','A pharmacy stores staff meals beside medications because separate shelves are labeled.','약품 보관 장비의 food/drink 제한을 단순 선반 분리로 대체하지 않는다.')
add('STORAGE','A pharmacy rejects a dorm-style refrigerator with an internal freezer compartment for this storage use.','A pharmacy accepts a dorm-style refrigerator solely because a spot temperature reading is within range.','장비 형식 적격성과 순간 온도는 별개이다.')
add('STORAGE','A pharmacy maintains required temperature logs and records the assessment of an excursion.','A pharmacy deletes excursion records after a manufacturer telephone discussion without retaining the disposition rationale.','Manufacturer consultation와 temperature/response documentation을 함께 유지한다.')
add('STORAGE','A pharmacy packages a shipped medication so transport does not adversely affect its integrity or stability.','A pharmacy assumes using a common carrier transfers all medication-stability responsibility away from the pharmacy.','배송 위탁과 pharmacy의 product-integrity/stability 책임은 다르다.')
add('STORAGE','A pharmacy examines a returned shipment’s actual chain of custody and temperature history before disposition.','A pharmacy considers an unopened-looking shipping carton conclusive proof of maintained temperature and integrity.','포장 외관만으로 보관·온도·인계 이력이 모두 적합했다고 확정하지 않는다.')
add('STORAGE','A pharmacy confirms its authority for dispensing into the destination jurisdiction before interstate shipment.','A pharmacy assumes its Massachusetts license alone authorizes shipments to every other jurisdiction.','출발지 면허와 도착지의 applicable nonresident requirements를 각각 확인한다.')
add('STORAGE','An authorized pharmacy follows the applicable USPS prescription-drug mailing conditions, including appropriate internal and external packaging.','An authorized pharmacy treats ordinary prescription legality as eliminating all USPS packaging and mailing restrictions.','Mailability와 legal dispensing는 다른 요건이다. 적격 발송자·포장·표시·운송경로를 함께 충족한다.')
add('STORAGE','A pharmacy verifies the patient’s delivery destination and provides a way to access pharmacist counseling.','A pharmacy treats shipment rather than counter pickup as a complete exemption from patient-information duties.','Mail/common-carrier delivery가 환자정보·상담 접근의 모든 의무를 없애지는 않는다.')

group('AUTO','Automation and shared-service boundaries',4,['w4-a-13','w4-a-14','w4-a-15','w4-a-16','w4-a-17','w4-a-18'],
      'A Massachusetts pharmacy evaluates automation. APS is a patient pickup system, PPA assists internal processing, and ADD is a healthcare-facility dispensing device.',
      '247 CMR 9.10–9.12; Policy 2021-02; Policy 2023-08')
add('AUTO','A qualifying APS is used for Schedule IV–VI prescriptions within the applicable security and patient-service conditions.','An APS is used for Schedule II prescriptions solely because its doors have barcode locks.','APS 허용 schedules와 보안기술은 다른 조건이다. IV–VI 범위를 CII로 넓히지 않는다.')
add('AUTO','An APS is located in the same building as the operating pharmacy and secured as required.','An APS is treated as compliant solely because it is in the same shopping center, in a different building.','Same building 조건을 같은 상가/주소권역으로 대체하지 않는다.')
add('AUTO','A pharmacy excludes medications requiring refrigeration or reconstitution from its APS.','A pharmacy places a medication requiring reconstitution into its APS with a leaflet asking the patient to mix it.','APS의 refrigeration/reconstitution 제한을 환자 leaflet으로 우회하지 않는다.')
add('AUTO','The pharmacy provides an opportunity for pharmacist consultation during all APS dispensing hours.','The pharmacy operates the APS after hours with pharmacist consultation available only during the pharmacy’s shorter opening hours.','현재 regulation의 APS consultation은 APS dispensing가 이루어지는 모든 시간에 적용된다.')
add('AUTO','A patient may choose not to use the APS and use an available lawful alternative pickup route.','A pharmacy makes APS use compulsory for every patient despite the patient-choice requirement.','APS에는 patient choice 조건이 포함된다.')
add('AUTO','When one commingled lot is recalled, the pharmacy quarantines all affected commingled lots under its PPA procedure.','When one commingled lot is recalled, the pharmacy keeps the mixed cell active because some tablets came from another lot.','PPA의 commingled lots는 구분할 수 없는 recall risk를 함께 관리한다.')
add('AUTO','An ADD in a licensed healthcare facility releases medication under a valid patient-specific prescription or order.','An ADD in a healthcare facility is treated as unrestricted office stock with no patient-specific prescription or order.','ADD 위치와 patient-specific authorization 요건을 모두 충족한다.')
add('AUTO','A remote pharmacist completes an authorized clinical activity while required onsite staffing and dispensing controls remain in place.','A remote pharmacist’s video availability is treated as blanket permission for technicians to fill and dispense without an onsite pharmacist in Massachusetts.','Telepharmacy clinical/final-product verification 경로와 technician-only filling/dispensing를 구별한다.')
add('AUTO','A shared-service agreement identifies the participating pharmacies’ tasks, records, and responsibilities.','Participating pharmacies treat common ownership as eliminating the need to establish shared-service responsibilities and records.','같은 소유주라는 사정이 applicable shared-service requirements를 없애지 않는다.')
add('AUTO','A pharmacy retains pharmacist responsibility for final patient-specific verification despite using automated counting.','A pharmacy replaces final pharmacist verification with a counting machine’s accuracy certification alone.','PPA/automation의 기술적 처리와 final professional validation은 별개이다.')

group('COMPOUND','Nonsterile compounding and patient need',4,['w4-b-1','w4-b-2','w4-b-3','w4-b-4','w4-b-6','w4-b-7','w4-b-8','w4-b-9','w4-b-10'],
      'A Massachusetts retail pharmacy reviews nonsterile preparations. It is not relying on a special shortage enforcement policy or a veterinary office-use exception.',
      'M.G.L. c.112 §39D; Policy 2023-07; FD&C Act §503A; applicable USP <795>')
add('COMPOUND','A pharmacy distinguishes simple reconstitution exactly under the manufacturer’s approved instructions from compounding.','A pharmacy treats a change to the manufacturer’s diluent and concentration as the same unchanged reconstitution exception.','Manufacturer directions 그대로인 행위와 formulation을 바꾼 조제를 구별한다.')
add('COMPOUND','A pharmacist adding flavoring to a requested Schedule VI medication evaluates and records concentration and stability effects.','A pharmacist adds flavoring without evaluating concentration or stability because flavoring is never compounding.','현재 MA policy는 flavoring을 compounding로 다루며 적절한 기록·stability/concentration 확인을 요구한다.')
add('COMPOUND','A pharmacy dispensing a patient-specific compound links the preparation to the required valid patient prescription.','A pharmacy uses ordinary 503A status to sell unlimited patient-unspecified office stock in the stated retail setting.','환자별 dispensing와 제한적 anticipatory preparation을 일반 office-stock 판매로 확대하지 않는다.')
add('COMPOUND','A prescriber documents a patient-specific medical need for a significant difference from an available commercial product.','A pharmacy uses a lower selling price alone as the documented medical need for copying an available commercial product.','MA의 significant-difference 경로는 documented medical need이며 cost만으로 충족되지 않는다.')
add('COMPOUND','A pharmacy checks that bulk API is eligible, properly sourced, and accompanied by the applicable valid COA.','A pharmacy uses research-only powder for a human preparation solely because the seller supplied a generic purity sheet.','COA나 외관이 허용되지 않은 원료·부적격 human-use source를 합법화하지 않는다.')
add('COMPOUND','A pharmacy obtains the required additional authority before making complex nonsterile preparations.','A pharmacy treats an ordinary Drug Store license as automatic authorization for every complex nonsterile dosage form.','Complex nonsterile에는 해당 specialty license와 시설·training 조건이 필요하다.')
add('COMPOUND','A pharmacy identifies hazardous-drug manipulation as requiring the applicable complex and containment controls.','A pharmacy treats crushing hazardous tablets into a suspension as ordinary nonhazardous tablet counting.','실제 manipulation와 노출 경로가 달라지면 HD·compounding 분류를 다시 적용한다.')
add('COMPOUND','A pharmacy maintains both the formulation instructions and a record of what was actually compounded.','A pharmacy keeps a generic recipe but no preparation-specific compounding record.','MFR는 만드는 방법, CR는 실제 제조 행위·원료·작업·검수·BUD 등 기록이다.')
add('COMPOUND','A pharmacist assigns a BUD considering the actual formulation, storage, container, and shorter stability limitations.','A pharmacist assigns one year to every compound by borrowing the general prescription-validity period.','Rx validity와 preparation BUD는 다른 시계이다. Default도 제품별 짧은 안정성 한계를 넘지 못한다.')
add('COMPOUND','A pharmacy follows a premeasured compounding kit’s applicable compounding and record requirements.','A pharmacy treats every premeasured kit as exempt from compounding standards simply because the quantities were packaged in advance.','Premeasured kit도 해당 compounding standards와 record requirements를 따른다.')

group('STERILE','Sterile preparation, testing, and release',4,['w4-b-12','w4-b-13','w4-b-14','w4-b-15','w4-b-17','w4-b-20','w4-b-21','w4-b-22','w4-b-23','w5-a-12'],
      'A Massachusetts sterile pharmacy evaluates a preparation and its release conditions. No unmentioned USP exception or Board waiver is being used.',
      'Current USP <797> framework; Massachusetts sterile-compounding policies; c.112 §39D')
add('STERILE','A compounder distinguishes Category 1–3 requirements from the former low-, medium-, and high-risk labels.','A compounder assigns current categories by simply renaming the former low-, medium-, and high-risk labels.','현재 Category는 시설·BUD·시험·인력/모니터링 요건이 연결된 체계이며 옛 risk 명칭의 단순 번호 변경이 아니다.')
add('STERILE','An immediate-use preparation meeting all other conditions is administered within the applicable time measured from preparation start.','An immediate-use preparation receives a new clock each time it is moved between clinical areas.','Immediate-use 시간은 preparation 시작점에 연결된다. 이동이 새 clock를 만들지 않는다.')
add('STERILE','A pharmacist distinguishes a source vial’s puncture/in-use limit from the finished CSP’s assigned BUD.','A pharmacist treats the finished CSP’s BUD as automatically extending the source vial’s permitted puncture time.','원료 용기 open/in-use와 최종 preparation BUD는 다른 제한이다.')
add('STERILE','A facility checks the appropriate environmental and engineering controls before claiming a longer-category BUD.','A facility assigns a longer-category BUD solely because the final solution looks clear.','외관만으로 category의 시설·process·testing 조건을 충족했다고 볼 수 없다.')
add('STERILE','A pharmacist confirms that required sterility-test results are negative before releasing the CSP under the applicable MA policy.','A pharmacist releases a CSP requiring sterility testing while results are pending, planning to recall only if positive.','MA의 해당 sterility-test-required release 조건을 충족해야 한다. 사후 recall 계획은 사전 시험의 대체가 아니다.')
add('STERILE','A pharmacist evaluates endotoxin control separately from a sterilizing filter’s integrity result.','A pharmacist treats a passing filter-integrity result as proof that endotoxin is absent.','Sterility/filtration integrity와 endotoxin control은 동일한 시험·위험이 아니다.')
add('STERILE','A compounder verifies chemical stability when selecting a microbial maximum BUD.','A compounder exceeds known chemical stability because the microbial BUD table allows a longer period.','Microbial maximum은 더 짧은 chemical/physical stability를 무시하는 보증 기간이 아니다.')
add('STERILE','Personnel complete the role-appropriate initial and ongoing competency assessment for the work performed.','Personnel replace every hands-on aseptic competency assessment with an unrelated CE certificate.','CE 이수와 garbing/aseptic process 등 실제 competency는 별개이다.')
add('STERILE','A pharmacist evaluates stability throughout the intended use of a compounded implantable-pump preparation.','A pharmacist assumes meeting the preparation’s release date alone establishes stability throughout a prolonged implanted infusion.','Dispensing 시점의 BUD 판단 외에 실제 사용 환경·전체 투약기간의 안정성을 확인해야 한다.')
add('STERILE','A pharmacy investigates a failed preparation test and related batches rather than erasing the initial failure with repeat testing alone.','A pharmacy treats one later passing result as sufficient to delete the original failure and omit investigation.','Repeat testing 자체는 원인 조사·영향평가·disposition의 대체가 아니다.')

group('HD','Hazardous handling and outsourcing distinctions',4,['w4-c-1','w4-c-2','w4-c-3','w4-c-4','w4-c-5','w4-c-6','w4-c-7','w4-c-8','w4-c-9','w4-c-10'],
      'A pharmacist evaluates handling and sourcing controls. Hazardous-drug exposure, controlled-substance scheduling, and FDA outsourcing registration are distinct classifications.',
      'USP <800> framework; Massachusetts HD advisory; FD&C Act §§503A–503B')
add('HD','A pharmacy evaluates hazardous handling even when the drug is not federally scheduled.','A pharmacy excludes a drug from hazardous handling solely because it has no federal controlled-substance schedule.','Occupational hazard와 abuse/diversion schedules는 다른 분류이다.')
add('HD','A facility reassesses exposure controls when an intact hazardous tablet will instead be crushed for compounding.','A facility applies the intact-tablet counting assessment unchanged to pulverization because the ingredient is the same.','제형·작업·노출경로가 바뀌면 AOR/containment를 다시 평가한다.')
add('HD','A pharmacy selects chemotherapy gloves meeting the applicable performance standard for the task.','A pharmacy treats any nitrile glove as automatically equivalent to tested chemotherapy gloves.','소재 이름만으로 요구되는 chemo-tested 성능이 입증되지 않는다.')
add('HD','A facility distinguishes deactivation, decontamination, cleaning, and disinfection when designing the cleaning process.','A facility treats a single alcohol wipe as automatically accomplishing every chemical and microbial control step.','각 단계는 목적이 다르며 적격 agent·순서·접촉시간·compatibility를 확인한다.')
add('HD','A pharmacy evaluates appropriate containment for hazardous compounding rather than relying on a product-protection hood alone.','A pharmacy assumes any sterile laminar-flow hood automatically protects workers from hazardous-drug exposure.','Aseptic product protection와 HD containment는 다른 목적이며 동시에 충족할 수 있어야 한다.')
add('HD','A pharmacy separates regulated hazardous waste handling from its ordinary controlled-substance accounting.','A pharmacy assumes sending controlled drugs to a reverse distributor automatically resolves every hazardous-waste obligation.','Reverse distribution authorization와 폐기물 유형별 EPA/state requirements를 구분한다.')
add('HD','A hospital distinguishes an appropriately registered 503B outsourcing facility’s supply pathway from a traditional 503A pharmacy’s pathway.','A hospital treats every state-licensed 503A pharmacy as a federally registered 503B outsourcing facility.','503A/503B는 서로 다른 법적 조건·registration·cGMP·supply 경로이다.')
add('HD','A purchaser recognizes that FDA outsourcing registration is not FDA approval of every compounded product.','A purchaser advertises every compounded preparation as FDA-approved merely because the supplier is registered under 503B.','Facility registration과 product approval은 다르다.')
add('HD','A 503B facility maintains applicable cGMP obligations for its outsourcing operation.','A 503B facility claims the traditional 503A cGMP exemption simply because both facilities compound medications.','503B는 cGMP 적용이며 적격503A의 특정 면제와 구별한다.')
add('HD','A pharmacy checks Massachusetts authority as well as federal outsourcing registration before sourcing for MA patients.','A pharmacy assumes a name on FDA’s outsourcing list alone establishes every Massachusetts licensing condition.','Federal registration과 MA license/registration을 각각 확인한다.')

group('SUPPLY','Supply-chain quality and FDA status',4,['w4-c-17','w4-c-18','w4-c-19','w4-c-20','w6-a-2','w6-a-4','w6-a-5','w6-a-6','ndc-approval','recall-classification'],
      'A pharmacy is evaluating product status and a supply-chain incident. No conclusion about a product’s current marketing availability is inferred from an old brand-name listing.',
      'FD&C Act §582; FDA application, recall, and drug-listing guidance')
add('SUPPLY','A pharmacy verifies both the supplier’s authorized status and the received product’s condition.','A pharmacy treats an authorized supplier’s invoice as conclusive proof that a damaged shipment is usable.','Trading-partner authorization와 실제 product integrity는 별도이다.')
add('SUPPLY','A pharmacy quarantines and investigates a suspect product before deciding whether the illegitimate-product reporting trigger is met.','A pharmacy treats every initial suspicion as an already confirmed illegitimate determination without investigation.','Suspect와 illegitimate의 판단 단계·reporting trigger를 구분한다.')
add('SUPPLY','A pharmacy preserves tracing and investigation records required by the applicable DSCSA pathway.','A pharmacy treats a limited enhanced-tracing exemption as eliminating every suspect-product and recordkeeping obligation.','한시적·일부 면제는 DSCSA 전체 의무 면제가 아니다. 이 문항은 면제의 특정 미래 날짜를 단정하지 않는다.')
add('SUPPLY','A pharmacist recognizes an NDC as an identifier rather than standalone proof of FDA approval.','A pharmacist treats any listed NDC as definitive evidence that FDA approved the product’s safety and effectiveness.','Drug listing/identifier와 approval decision은 다르다.')
add('SUPPLY','A pharmacist distinguishes an investigational IND pathway from ordinary marketing approval.','A pharmacist treats an IND number as permission to sell the investigational drug through routine retail prescriptions.','IND는 연구 경로이며 일반 판매승인을 의미하지 않는다.')
add('SUPPLY','A pharmacist distinguishes an OTC monograph pathway from an individual approved drug application.','A pharmacist concludes that OTC status means the product is outside FDA drug regulation.','OTC에도 해당 monograph/application 및 다른 법적 요건이 적용된다.')
add('SUPPLY','A pharmacy follows a recall notice while FDA classification is still pending when its affected stock has been identified.','A pharmacy refuses to act on an identified recall until FDA assigns Class I, II, or III.','Not-yet-classified 상태가 환자 보호 조치를 미룰 이유는 아니다. Recall initiation와 classification 날짜는 다를 수 있다.')
add('SUPPLY','A pharmacy distinguishes an internal stock recovery before release from a marketed-product recall.','A pharmacy labels every correction to stock still under the manufacturer’s direct control as a marketed-product recall.','Stock recovery, market withdrawal, recall의 정의·유통 상태를 구별한다.')
add('SUPPLY','A pharmacist interprets recall Class I as a health-risk classification rather than a controlled-drug schedule.','A pharmacist handles a Class I recall as though every affected product had become Schedule I.','FDA recall class와 DEA schedule은 다른 분류이다.')
add('SUPPLY','A pharmacist checks the conditions and current status of an EUA separately from full approval.','A pharmacist advertises an EUA as identical to unrestricted full marketing approval for all populations.','EUA의 대상·조건·기간과 정식 approval은 다르다.')

group('CQI','Error response, product defects, and reporting',4,['w4-d-1','w4-d-2','w4-d-3','w4-d-4','w4-d-5','w4-d-6','w4-d-7','w4-d-8','parallel-duties'],
      'A Massachusetts pharmacy is responding to a quality event. Patient protection, internal CQI, product recall, and agency reporting are evaluated separately.',
      '247 CMR 15,20; M.G.L. c.112 §39D; Policies 2025-02 and 2024-04')
add('CQI','A pharmacist promptly informs the patient or representative of a discovered dispensing error and gives appropriate corrective instructions.','A pharmacist postpones all patient contact until the next scheduled CQI meeting despite a discovered error affecting the patient.','해당 QRE의 즉시 환자 통지·교정/위해감소 조치와 이후 CQI 분석은 별개이다.')
add('CQI','A pharmacy begins the required QRE record within 24 hours after the pharmacist discovers or is informed of the event.','A pharmacy starts the 24-hour QRE documentation clock only after the complete root-cause investigation ends.','Clock는 discovery/being informed에서 시작하며 조사완료가 아니다. 추가내용은 보완한다.')
add('CQI','A pharmacy treats a near miss caught before the patient receives the medication as distinct from the policy’s patient-received QRE definition.','A pharmacy assumes every near miss requires identical patient-error notification even when no medication reached a patient.','Near miss도 유용한 안전분석 대상이지만 patient-received QRE와 정의·통지 trigger가 다르다.')
add('CQI','A pharmacy evaluates a serious event that caused additional emergency-department monitoring even without an inpatient admission.','A pharmacy excludes an event from serious-injury consideration solely because the patient was not admitted overnight.','정의에 hospital/ED 추가 treatment/testing/monitoring가 포함될 수 있다. Inpatient admission만이 유일 기준은 아니다.')
add('CQI','A pharmacy keeps CQI records and separately completes any applicable external serious-event report.','A pharmacy treats completion of its internal CQI form as completing every Board, FDA, or other agency report.','Internal quality system과 기관별 reporting은 병렬 의무이다.')
add('CQI','A pharmacy promptly recalls and quarantines a preparation it knows or has reason to believe is defective.','A pharmacy delays action on a known defective preparation until a patient is proven to have suffered injury.','Defect 대응은 실제 injury가 확인되어야만 시작하는 체계가 아니다.')
add('CQI','A pharmacy records affected preparations and maintains the required defective-preparation log and related disposition records.','A pharmacy deletes all defective-preparation tracking after sending one recall notice.','Recall notice가 log·수량 추적·보존·기관보고를 모두 대체하지 않는다.')
add('CQI','A pharmacy evaluates related batches sharing the implicated component lot or process when a test fails.','A pharmacy considers only the single tested vial and declines to assess related batches sharing the implicated process.','실패 원인과 공통 component/process에 따라 범위 영향을 평가한다.')
add('CQI','A CQI program reviews contributing workflow factors and checks whether corrective measures work.','A CQI program closes every event after naming the employee without evaluating recurrence or system factors.','CQI의 목적에는 detect/document/assess/prevent와 effectiveness 검토가 포함된다.')
add('CQI','A pharmacy preserves the earliest applicable reporting trigger while investigating the event.','A pharmacy restarts an agency reporting clock when the MOR eventually reads an event already known to pharmacy personnel.','의무별 trigger는 discovery/employee awareness 등 원문 기준이며 MOR가 늦게 읽었다고 임의 재설정하지 않는다.')

