for _g in GROUPS.values():
    for _a in _g['atoms']:
        if _a['id'] in BAD_ACTION_REVISIONS:_a['bad']=BAD_ACTION_REVISIONS[_a['id']]
assert set(BAD_ACTION_REVISIONS).issubset({_a['id'] for _g in GROUPS.values() for _a in _g['atoms']})
